      parts.push({ 
        inlineData: { 
          mimeType: mimeType, 
          data: data 
        } 
      });
    }

    parts.push({ 
      text: "Extract all multiple choice questions from this document. Also generate a short, descriptive title for this exam based on the content (e.g. 'History Practice 1', 'Math Chapter 3')." 
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        maxOutputTokens: 8192, // Explicitly set high limit for long exams
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "A generated title for the exam" },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.INTEGER },
                  text: { type: Type.STRING },
