    }

    // Transform to match our internal State interface exactly
    const questions: Question[] = responseData.questions.map((q: any) => ({
      id: q.id,
      text: q.text,
      options: q.options,
      correctAnswerLabel: q.correctAnswerLabel,
      userSelection: null
    }));

    return {
      title: responseData.title || "Yeni Sınav",
      questions
    };

  } catch (error) {
    console.error("Gemini parse error:", error);
    throw error;
  }
};

