                    labelClass += "text-green-700 dark:text-green-400";
                    textClass += "text-gray-900 dark:text-gray-100";
                  } else {
                    containerClass += "border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-500 hover:bg-gray-50 dark:hover:bg-gray-800";
                    labelClass += "text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200";
                    textClass += "text-gray-900 dark:text-gray-300";
                  }
                } else {
                  // Finished State
                  if (isCorrect) {
                    // Doğru cevap (Yeşil)
                    containerClass += "border-green-500 bg-green-100/40 dark:bg-green-900/40 shadow-sm"; 
                    textClass += "text-green-800 dark:text-green-400 font-bold";
                    labelClass += "text-green-800 dark:text-green-400 font-bold";
                  } else if (isSelected) {
                    // Yanlış işaretlenmiş (Kırmızı)
                    containerClass += "border-red-500 bg-red-50 dark:bg-red-900/20 shadow-sm";
                    textClass += "text-red-700 dark:text-red-400 font-bold";
                    labelClass += "text-red-700 dark:text-red-400 font-bold";
                  } else {
                    // Diğer şıklar (Siyah/Nötr)
                    containerClass += "border-gray-200 dark:border-gray-700 opacity-60";
                    textClass += "text-gray-900 dark:text-gray-400";
                    labelClass += "text-gray-900 dark:text-gray-400 font-medium";
                  }
                }

                return (
                  <button
                    key={opt.label}
                    onClick={() => handleOptionSelect(q.id, opt.label)}
                    disabled={exam.isFinished}
                    className={containerClass}
                  >
                    <span className={labelClass}>{opt.label})</span>
                    <span className={textClass}>{opt.text}</span>

                    {/* Active State Icon */}
                    {isSelected && !exam.isFinished && (
                      <CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-500" />
                    )}

                    {/* Finished State Icons */}
                    {exam.isFinished && isCorrect && (
                      <CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-600 dark:text-green-400" />
                    )}
                    {exam.isFinished && isSelected && !isCorrect && (
                      <XCircle className="absolute right-3 top-3 w-5 h-5 text-red-500 dark:text-red-400" />
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        ))}

        {!exam.isFinished && (
          <div className="mt-8 mb-12 flex justify-center">
            <button
              onClick={finishExam}
              className="bg-blue-600 text-white text-lg font-bold py-4 px-12 rounded-full shadow-lg hover:bg-blue-700 hover:shadow-xl transform hover:-translate-y-1 transition-all active:scale-95 dark:shadow-blue-900/50"
            >
              SINAVI BİTİR
            </button>
          </div>
        )}

        {exam.isFinished && (
          <div className="mt-8 mb-12 p-6 bg-gray-100 dark:bg-gray-800 rounded-xl text-center border border-gray-200 dark:border-gray-700">
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">Sınav Tamamlandı</h3>
            <p className="text-gray-600 dark:text-gray-400 mb-4">Cevaplarınızı kontrol edin. Doğru şıklar yeşil, yanlış işaretlediğiniz şıklar kırmızı ile belirtilmiştir.</p>
            <button 
              onClick={onResetRequest}
              className="bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 font-semibold py-2 px-6 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 transition"
            >
              Yeniden Çalış
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  // --- Auth State ---
  // Lazy initialization to prevent login screen flash on refresh
  const [currentUser, setCurrentUser] = useState<string | null>(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('sinav_asistani_active_user');
    }
    return null;
  });

  // Flag to ensure we don't overwrite local storage with empty data before loading
  const [isInitialized, setIsInitialized] = useState(false);

  // --- State ---
  const [folders, setFolders] = useState<Folder[]>([]);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null);
  const [activeExamId, setActiveExamId] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string | null>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);

  // Folder Renaming State (Detail View)
  const [isEditingFolderName, setIsEditingFolderName] = useState(false);
  const [tempFolderName, setTempFolderName] = useState("");

  // Folder Renaming State (Dashboard View)
  const [editingFolderId, setEditingFolderId] = useState<string | null>(null);
  const [editFolderTempName, setEditFolderTempName] = useState("");

  // Modals State
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [examToDeleteId, setExamToDeleteId] = useState<string | null>(null);

  // --- Persistence & Theme ---

  // Load Theme
  useEffect(() => {
    const savedTheme = localStorage.getItem('sinav_asistani_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setDarkMode(true);
    }
  }, []);

  // Load User Data & UI State
  useEffect(() => {
    if (currentUser) {
      setIsInitialized(false);

      // 1. Load Data
      const savedData = localStorage.getItem(`sinav_asistani_data_${currentUser}`);
      if (savedData) {
        try {
          setFolders(JSON.parse(savedData));
        } catch (e) {
          console.error("Data load error", e);
          setFolders([]);
        }
      } else {
        setFolders([]);
      }

      // 2. Load UI State (View, Active IDs)
      const savedUi = localStorage.getItem(`sinav_asistani_ui_${currentUser}`);
      if (savedUi) {
        try {
          const ui = JSON.parse(savedUi);
          if (ui.currentView) setCurrentView(ui.currentView);
          if (ui.activeFolderId) setActiveFolderId(ui.activeFolderId);
          if (ui.activeExamId) setActiveExamId(ui.activeExamId);
        } catch (e) {
          console.error("UI state load error", e);
        }
      }

      setIsInitialized(true);
    }
  }, [currentUser]);

  // Save Data & UI State
  useEffect(() => {
    if (currentUser && isInitialized) {
      // Save Data
      localStorage.setItem(`sinav_asistani_data_${currentUser}`, JSON.stringify(folders));

      // Save UI State
      const uiState = {
        currentView,
        activeFolderId,
        activeExamId
      };
      localStorage.setItem(`sinav_asistani_ui_${currentUser}`, JSON.stringify(uiState));

      // Save Active User
      localStorage.setItem('sinav_asistani_active_user', currentUser);
    }
  }, [folders, currentView, activeFolderId, activeExamId, currentUser, isInitialized]);

  // Validate Navigation State
  // If a folder/exam is deleted or doesn't exist in loaded data, revert view
  useEffect(() => {
    if (!isInitialized) return;

    if (activeFolderId) {
        const folder = folders.find(f => f.id === activeFolderId);
        if (!folder) {
            setActiveFolderId(null);
            setCurrentView('DASHBOARD');
            return;
        }

        if (activeExamId) {
            const exam = folder.exams.find(e => e.id === activeExamId);
            if (!exam) {
                setActiveExamId(null);
                setCurrentView('FOLDER_DETAIL');
            }
        }
    }
  }, [folders, activeFolderId, activeExamId, isInitialized]);

  // Handle Theme Change
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('sinav_asistani_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('sinav_asistani_theme', 'light');
    }
  }, [darkMode]);

  // Sync temp folder name when entering a folder
  useEffect(() => {
    if (activeFolderId) {
      const folder = folders.find(f => f.id === activeFolderId);
      if (folder) setTempFolderName(folder.name);
    }
  }, [activeFolderId, folders]);

  // --- Actions ---

  const handleLogin = (username: string) => {
    setCurrentUser(username);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setFolders([]);
    setActiveFolderId(null);
    setActiveExamId(null);
    setCurrentView('DASHBOARD');
    localStorage.removeItem('sinav_asistani_active_user');
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  const createFolder = () => {
    const newId = crypto.randomUUID();
    const defaultName = "Yeni Klasör";
    const newFolder: Folder = {
      id: newId,
      name: defaultName,
      exams: []
    };
    setFolders(prev => [...prev, newFolder]);

    // Automatically enter edit mode for the new folder
    setEditingFolderId(newId);
    setEditFolderTempName(defaultName);
  };

  const deleteFolder = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Bu klasörü ve içindeki tüm sınavları silmek istediğinize emin misiniz?")) {
      setFolders(folders.filter(f => f.id !== id));
      if (activeFolderId === id) {
        setActiveFolderId(null);
        setCurrentView('DASHBOARD');
      }
    }
  };

  const startEditingFolder = (e: React.MouseEvent, folder: Folder) => {
    e.stopPropagation();
    setEditingFolderId(folder.id);
    setEditFolderTempName(folder.name);
  };

  const saveFolderEdit = (e: React.MouseEvent | React.FormEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    if (editingFolderId && editFolderTempName.trim()) {
      setFolders(prev => prev.map(f => f.id === editingFolderId ? { ...f, name: editFolderTempName } : f));
      setEditingFolderId(null);
    } else {
      setEditingFolderId(null);
    }
  };

  const cancelFolderEdit = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    setEditingFolderId(null);
  };

  const saveFolderNameDetail = () => {
    if (activeFolderId && tempFolderName.trim()) {
      setFolders(prev => prev.map(f => f.id === activeFolderId ? { ...f, name: tempFolderName } : f));
      setIsEditingFolderName(false);
    } else {
      // Revert
      const folder = folders.find(f => f.id === activeFolderId);
      if (folder) setTempFolderName(folder.name);
      setIsEditingFolderName(false);
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>, targetFolderId?: string) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    // Use specific folder or active folder
    let folderId = targetFolderId || activeFolderId;
    let isNewFolder = false;
    let newFolderId = "";

    // If no folder is selected, create one implicitly
    if (!folderId) {
      isNewFolder = true;
      newFolderId = crypto.randomUUID();
      folderId = newFolderId;
      // Initialize the folder immediately so we can add to it
      const newFolder: Folder = { id: newFolderId, name: "Genel", exams: [] };
      setFolders(prev => [...prev, newFolder]);
    }

    setCurrentView('LOADING');

    // Process each file sequentially to avoid overwhelming state updates or API
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setLoadingMessage(`Dosya işleniyor (${i + 1}/${files.length}): ${file.name}`);

      try {
        const mimeType = getMimeType(file);
        let data = '';

        // Handle text vs binary
        if (mimeType.startsWith('text/')) {
          data = await fileToText(file);
        } else {
          data = await fileToBase64(file);
        }

        const parsedData = await parseExamFile(data, mimeType);

        const newExam: Exam = {
          id: crypto.randomUUID(),
          title: parsedData.title,
          dateCreated: new Date().toISOString(),
          questions: parsedData.questions,
          isFinished: false
        };

        setFolders(prev => prev.map(f => {
          if (f.id === folderId) {
            return { ...f, exams: [...f.exams, newExam] };
          }
          return f;
        }));

        // Only set active exam if it's the last file and we are not in folder detail view already
        if (i === files.length - 1) {
            if (!activeFolderId) {
                 setActiveFolderId(folderId);
                 setActiveExamId(newExam.id);
                 setCurrentView('EXAM_TAKER');
            } else {
                 // Stick to folder view if we were already in a folder or uploaded multiple
                 setCurrentView('FOLDER_DETAIL');
            }
        }

      } catch (error) {
        console.error(`Error processing file ${file.name}:`, error);
        alert(`Hata: ${file.name} dosyası işlenemedi.`);
      }
    }

    setLoadingMessage(null);
  };

  const updateExamInState = (updatedExam: Exam) => {
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return {
          ...f,
          exams: f.exams.map(e => e.id === updatedExam.id ? updatedExam : e)
        };
      }
      return f;
    }));
  };

  // --- Reset & Archive Logic ---

  const handleResetRequest = () => {
    setIsResetModalOpen(true);
  };

  const handleArchiveAndReset = () => {
    if (!activeFolderId || !activeExamId) return;

    setFolders(prev => {
      return prev.map(f => {
        if (f.id === activeFolderId) {
          const currentExam = f.exams.find(e => e.id === activeExamId);
          if (!currentExam) return f;

          // 1. Create a deep copy for the archive
          const dateStr = new Date().toLocaleDateString('tr-TR', { hour: '2-digit', minute: '2-digit' });
          const archivedExam: Exam = {
            ...JSON.parse(JSON.stringify(currentExam)), // Deep clone to preserve answers
            id: crypto.randomUUID(),
            title: `${currentExam.title} (Tamamlandı - ${dateStr})`,
            isFinished: true, // Ensure it stays finished
          };

          // 2. Reset the current exam in place
          const resetExam: Exam = {
            ...currentExam,
            isFinished: false,
            questions: currentExam.questions.map(q => ({ ...q, userSelection: null }))
          };

          // Return folder with both archived exam appended and current exam reset
          return {
            ...f,
            exams: [...f.exams.filter(e => e.id !== activeExamId), archivedExam, resetExam]
          };
        }
        return f;
      });
    });

    setIsResetModalOpen(false);
    // Note: activeExamId stays the same, so UI updates to show the reset version automatically
  };

  const handleJustReset = () => {
    if (!activeFolderId || !activeExamId) return;

    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return {
          ...f,
          exams: f.exams.map(e => {
            if (e.id === activeExamId) {
              return {
                ...e,
                isFinished: false,
                questions: e.questions.map(q => ({ ...q, userSelection: null }))
              };
            }
            return e;
          })
        };
      }
      return f;
    }));
    setIsResetModalOpen(false);
  };

  // --- Delete Exam ---

  const requestDeleteExam = (e: React.MouseEvent, examId: string) => {
    e.stopPropagation();
    setExamToDeleteId(examId);
  };

  const confirmDeleteExam = () => {
    if (!examToDeleteId) return;

    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return { ...f, exams: f.exams.filter(ex => ex.id !== examToDeleteId) };
      }
      return f;
    }));

    setExamToDeleteId(null);
  };

  // --- Rendering Helpers ---

  const renderDashboard = () => (
    <div className="p-6 max-w-5xl mx-auto w-full flex flex-col h-full">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Sınav Kitaplığım</h1>
        <button 
          onClick={createFolder}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg font-medium transition shadow-md shadow-blue-500/20"
        >
          <Plus className="w-5 h-5" />
          <span>Yeni Klasör</span>
        </button>
      </div>

      {folders.length === 0 ? (
        <div className="flex-1 flex flex-col items-center justify-center -mt-20">
          <div className="bg-white dark:bg-gray-800 p-10 rounded-3xl shadow-xl border border-blue-100 dark:border-gray-700 text-center max-w-lg w-full transform hover:scale-[1.01] transition-all">
            <div className="bg-blue-50 dark:bg-blue-900/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6">
              <Upload className="w-10 h-10 text-blue-600 dark:text-blue-400" />
            </div>
            <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-3">Sınav Asistanına Hoşgeldiniz</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-8">
              Sınav hazırlığına başlamak için dosyanızı yükleyin. Sorular otomatik olarak taranıp test haline getirilecektir.
            </p>
            <label className="block w-full cursor-pointer">
              <div className="bg-blue-600 hover:bg-blue-700 text-white text-lg font-bold py-4 px-6 rounded-xl shadow-lg transition flex items-center justify-center gap-3 shadow-blue-500/30">
                <Upload className="w-6 h-6" />
                Dosyayı Yükle
              </div>
              <input 
                type="file" 
                multiple
                accept=".pdf,.jpg,.jpeg,.png,.bmp,.ai,.xlsx,.htm,.html,.txt,.docx" 
                onChange={(e) => handleFileUpload(e)} 
                className="hidden" 
              />
            </label>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-4">
              Desteklenen formatlar: PDF, JPG, PNG, AI, BMP, XLSX, DOCX, TXT, HTML
            </p>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {folders.map(folder => (
            <div 
              key={folder.id}
              onClick={() => { setActiveFolderId(folder.id); setCurrentView('FOLDER_DETAIL'); }}
              className="group bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 hover:shadow-lg hover:border-blue-200 dark:hover:border-blue-500/50 transition-all cursor-pointer relative"
            >
              <div className="flex items-start justify-between mb-4">
                <div className="p-3 bg-blue-50 dark:bg-blue-900/30 rounded-xl group-hover:bg-blue-100 dark:group-hover:bg-blue-900/50 transition">
                  <FolderIcon className="w-8 h-8 text-blue-600 dark:text-blue-400" />
                </div>
                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={(e) => startEditingFolder(e, folder)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-500 dark:text-gray-400">
                    <Edit2 className="w-4 h-4" />
                  </button>
                  <button onClick={(e) => deleteFolder(e, folder.id)} className="p-1.5 hover:bg-red-50 dark:hover:bg-red-900/30 rounded text-red-500 dark:text-red-400">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>

              {editingFolderId === folder.id ? (
                <div className="mb-1 flex items-center gap-2" onClick={e => e.stopPropagation()}>
                    <input 
                        type="text" 
                        value={editFolderTempName}
                        onChange={(e) => setEditFolderTempName(e.target.value)}
                        className="w-full border border-blue-400 rounded px-2 py-1 text-lg font-bold bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                        autoFocus
                        onKeyDown={(e) => {
                            if(e.key === 'Enter') saveFolderEdit(e);
                            if(e.key === 'Escape') cancelFolderEdit(e);
                        }}
                        onClick={e => e.stopPropagation()}
                    />
                    <button onClick={saveFolderEdit} className="p-1 text-green-600 hover:bg-green-100 dark:hover:bg-green-900/30 rounded flex-shrink-0">
                        <CheckCircle className="w-5 h-5" />
                    </button>
                     <button onClick={cancelFolderEdit} className="p-1 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/30 rounded flex-shrink-0">
                        <XCircle className="w-5 h-5" />
                    </button>
                </div>
              ) : (
                <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-1 truncate">{folder.name}</h3>
              )}

              <p className="text-gray-500 dark:text-gray-400 text-sm">{folder.exams.length} Sınav</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderFolderDetail = () => {
    const activeFolder = folders.find(f => f.id === activeFolderId);
    if (!activeFolder) return null;

    return (
      <div className="p-6 max-w-5xl mx-auto w-full h-full flex flex-col">
        <div className="flex items-center gap-4 mb-8">
          <button 
            onClick={() => { setActiveFolderId(null); setCurrentView('DASHBOARD'); setIsEditingFolderName(false); }}
            className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition flex-shrink-0"
          >
            <ArrowLeft className="w-6 h-6 text-gray-700 dark:text-gray-200" />
          </button>

          <div className="flex-1 overflow-hidden">
            {isEditingFolderName ? (
              <div className="flex items-center gap-2 max-w-md">
                <input
                  type="text"
                  value={tempFolderName}
                  onChange={(e) => setTempFolderName(e.target.value)}
                  className="flex-1 border border-blue-300 dark:border-blue-500 rounded px-2 py-1 text-2xl font-bold focus:outline-none focus:ring-2 focus:ring-blue-500 bg-transparent text-gray-900 dark:text-white"
                  autoFocus
                  onKeyDown={(e) => e.key === 'Enter' && saveFolderNameDetail()}
                />
                <button onClick={saveFolderNameDetail} className="p-1 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/30 rounded">
                  <CheckCircle className="w-6 h-6" />
                </button>
                <button onClick={() => { setIsEditingFolderName(false); setTempFolderName(activeFolder.name); }} className="p-1 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded">
                  <XCircle className="w-6 h-6" />
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-3 group cursor-pointer" onClick={() => { setIsEditingFolderName(true); setTempFolderName(activeFolder.name); }}>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">{activeFolder.name}</h1>
                <Edit2 className="w-4 h-4 text-gray-400 dark:text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity" />
              </div>
            )}
            <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">Sınav Listesi</p>
          </div>

          <label className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg font-medium transition shadow-md cursor-pointer flex-shrink-0 shadow-blue-500/20">
            <Upload className="w-5 h-5" />
            <span>Dosyayı Yükle</span>
            <input 
              type="file" 
              multiple
              accept=".pdf,.jpg,.jpeg,.png,.bmp,.ai,.xlsx,.htm,.html,.txt,.docx" 
              onChange={handleFileUpload} 
              className="hidden" 
            />
          </label>
        </div>

        {activeFolder.exams.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center opacity-60">
            <div className="w-20 h-20 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4">
               <FileText className="w-10 h-10 text-gray-400 dark:text-gray-500" />
            </div>
            <h3 className="text-xl font-medium text-gray-700 dark:text-gray-300">Bu klasör henüz boş</h3>
            <p className="max-w-md mt-2 text-gray-500 dark:text-gray-400">Yukarıdaki "Dosyayı Yükle" butonuna basarak soru kitapçıklarınızı ekleyebilirsiniz.</p>
