import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

const SYSTEM_INSTRUCTION = `
You are an expert exam digitizer. Your task is to extract multiple-choice questions from the provided document.
1. Identify questions that are numbered (e.g., 1., 2., 3., etc.).
2. Extract the question text.
3. Extract options labeled A), B), C), D), E) (or similar variants like A., B.).
4. Look for an "Answer Key" or "Cevap Anahtarı" typically located at the end of the document or bottom of the page.
5. If an answer key exists, match the correct option to the question.
6. If no answer key is explicitly found, try to solve the question to identify the correct answer, but prioritize the printed answer key if available.
7. Return the output STRICTLY as a JSON array of questions.

IMPORTANT ERROR HANDLING:
8. If you encounter text, images, or sections that are blurry, unreadable, or not clearly a multiple-choice question, IGNORE THEM. 
9. DO NOT stop processing. Skip the unreadable part and continue to the next valid question.
10. DO NOT output partial or malformed JSON objects for bad data. Only output complete, valid question objects.
`;

export const parseExamFile = async (data: string, mimeType: string): Promise<{ title: string, questions: Question[] }> => {
  let text = "";
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // We use gemini-2.5-flash for speed and good vision capabilities
    const modelId = "gemini-2.5-flash";

    // Determine if we should send as text or inlineData
    const isText = mimeType.startsWith('text/');

    const parts = [];
    if (isText) {
      parts.push({ text: data });
    } else {
      parts.push({ 
        inlineData: { 
          mimeType: mimeType, 
          data: data 
        } 
      });
    }

    parts.push({ 
      text: "Extract all multiple choice questions from this document. Also generate a short, descriptive title for this exam based on the content (e.g. 'History Practice 1', 'Math Chapter 3')." 
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        maxOutputTokens: 8192, // Explicitly set high limit for long exams
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "A generated title for the exam" },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.INTEGER },
                  text: { type: Type.STRING },
                  options: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        label: { type: Type.STRING, description: "e.g. A, B, C, D, E" },
                        text: { type: Type.STRING }
                      }
                    }
                  },
                  correctAnswerLabel: { type: Type.STRING, nullable: true, description: "The label of the correct option (A, B, C...) if found or solved." }
                }
              }
            }
          }
        }
      }
    });

    text = response.text || "";
    if (!text) throw new Error("No response from AI");

    // Robust cleaning: remove markdown code blocks if present
    text = text.replace(/^```json\s*/gi, '').replace(/^```\s*/gi, '').replace(/```\s*$/gi, '').trim();

    let responseData;

    try {
        // Attempt 1: Standard Parse
        responseData = JSON.parse(text);
    } catch (e) {
        console.warn("JSON Parse failed, attempting to repair...", e);

        try {
            // Attempt 2: Truncation Repair (Fixing cut-off JSON at the end)
            const qStartIndex = text.indexOf('[');
            if (qStartIndex !== -1) {
                const lastObjectComma = text.lastIndexOf('},');
                if (lastObjectComma > qStartIndex) {
                    const repairedText = text.substring(0, lastObjectComma + 1) + ']}';
                    responseData = JSON.parse(repairedText);
                } else {
                     const lastBrace = text.lastIndexOf('}');
                     if (lastBrace > qStartIndex) {
                        const repairedText = text.substring(0, lastBrace + 1) + ']}';
                        responseData = JSON.parse(repairedText);
                     } else {
                        throw new Error("Cannot repair JSON structure");
                     }
                }
            } else {
                 throw new Error("No JSON array start found");
            }
        } catch (repairError) {
            console.error("Standard repair failed. Attempting strict object extraction to skip errors.", repairError);

            // Attempt 3: Regex Fallback (Skip invalid areas, extract valid objects individually)
            // This logic looks for patterns that resemble { "id": ... } and tries to parse them one by one.
            const extractedQuestions: any[] = [];

            // Regex to find potential question objects. 
            // It looks for a starting { followed eventually by "id" and "text", ending with a }
            // This is a "best effort" regex to identify blocks.
            const matches = text.match(/\{[\s\S]*?"id"[\s\S]*?"text"[\s\S]*?"options"[\s\S]*?\}(?=\s*,|\s*\])/g);

            if (matches && matches.length > 0) {
                matches.forEach(match => {
                    try {
                        const q = JSON.parse(match);
                        if (q.id && q.text && Array.isArray(q.options)) {
                            extractedQuestions.push(q);
                        }
                    } catch (ignore) { 
                        // If a specific block is corrupted, we skip it (as requested)
                    }
                });
            }

            // Fallback Title Extraction
            const titleMatch = text.match(/"title"\s*:\s*"([^"]+)"/);
            const fallbackTitle = titleMatch ? titleMatch[1] : "Kurtarılan Sınav (Kısmi Veri)";

            if (extractedQuestions.length > 0) {
                responseData = {
                    title: fallbackTitle,
                    questions: extractedQuestions
                };
            } else {
                // Return a safe empty result instead of throwing an error to the UI
                console.error("All parsing attempts failed. Returning safe empty object.");
                return {
                    title: "İşlenemeyen Dosya",
                    questions: []
                };
            }
        }
    }

    // Final validation and transformation
    const questions: Question[] = (responseData.questions || []).map((q: any) => ({
      id: q.id || Math.floor(Math.random() * 10000),
      text: q.text || "Soru metni okunamadı",
      options: Array.isArray(q.options) ? q.options : [],
      correctAnswerLabel: q.correctAnswerLabel,
      userSelection: null
    }));

    return {
      title: responseData.title || "Yeni Sınav",
      questions
    };

  } catch (error) {
    console.error("Gemini parse error (Final Catch):", error);
    // Ultimate fallback: do not crash the app logic.
    return {
        title: "Hata: Dosya Okunamadı",
        questions: []
    };
  }
};

