                    {exam.isFinished ? '✓' : '?'}
                  </div>
                  <div>
                    <h3 className="font-bold text-gray-800 dark:text-gray-100 text-lg group-hover:text-blue-700 dark:group-hover:text-blue-400 transition-colors">{exam.title}</h3>
