  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200 transition-colors">
        <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Çalışmayı Yenile</h3>
        <p className="text-gray-600 dark:text-gray-300 mb-6">Sınavı sıfırlamadan önce mevcut sonuçlarınızı ve işaretlemelerinizi bu klasöre kaydetmek ister misiniz?</p>
        <div className="flex flex-col gap-3">
          <button onClick={onSaveAndReset} className="w-full bg-blue-600 text-white font-semibold py-3 px-4 rounded-xl hover:bg-blue-700 transition flex items-center justify-center gap-2 shadow-lg shadow-blue-500/30"><Save className="w-5 h-5" />Sonucu Kaydet ve Sıfırla</button>
          <button onClick={onJustReset} className="w-full bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 font-semibold py-3 px-4 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-600 transition">Kaydetmeden Sıfırla</button>
          <button onClick={onClose} className="w-full text-gray-500 dark:text-gray-400 text-sm font-medium py-2 hover:text-gray-700 dark:hover:text-gray-200 transition">İptal</button>
        </div>
      </div>
    </div>
  );
};

