// 3. Exam Taker Component
interface ExamTakerProps {
  exam: Exam;
  onUpdateExam: (updatedExam: Exam) => void;
  onBack: () => void;
  onResetRequest: () => void;
}

const ExamTaker: React.FC<ExamTakerProps> = ({ exam, onUpdateExam, onBack, onResetRequest }) => {
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [tempTitle, setTempTitle] = useState(exam.title);
  const [isEditMode, setIsEditMode] = useState(false);

  // Sync temp title if exam changes externally
  useEffect(() => {
    setTempTitle(exam.title);
  }, [exam.title]);

  const handleOptionSelect = (questionId: number, label: string) => {
    if (isEditMode) return; // Disable answering in edit mode
    if (exam.isFinished) return;

    const updatedQuestions = exam.questions.map(q => {
      if (q.id === questionId) {
        // Toggle logic
        return { ...q, userSelection: q.userSelection === label ? null : label };
      }
      return q;
    });

    onUpdateExam({ ...exam, questions: updatedQuestions });
  };

  const finishExam = () => {
    onUpdateExam({ ...exam, isFinished: true });
    setTimeout(() => {
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    }, 100);
  };

  const saveTitle = () => {
    if (tempTitle.trim()) {
      onUpdateExam({ ...exam, title: tempTitle });
    } else {
      setTempTitle(exam.title); // Revert if empty
    }
    setIsEditingTitle(false);
  };

  // --- EDIT MODE HANDLERS ---

  const handleQuestionTextChange = (qId: number, text: string) => {
    const updated = exam.questions.map(q => q.id === qId ? { ...q, text } : q);
    onUpdateExam({ ...exam, questions: updated });
  };

  const handleOptionTextChange = (qId: number, optLabel: string, text: string) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        return {
          ...q,
          options: q.options.map(o => o.label === optLabel ? { ...o, text } : o)
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const toggleCorrectAnswer = (qId: number, label: string) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        // If clicking the current correct answer, unset it. Else set it.
        return { 
          ...q, 
          correctAnswerLabel: q.correctAnswerLabel === label ? null : label 
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const addOption = (qId: number) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        const labels = ["A", "B", "C", "D", "E", "F", "G"];
        const nextLabel = labels[q.options.length] || "X";
        return {
          ...q,
          options: [...q.options, { label: nextLabel, text: "" }]
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const removeOption = (qId: number, label: string) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        const filtered = q.options.filter(o => o.label !== label);
        // Re-label logic (optional, but keeps things clean A,B,C...)
        // For simplicity, we just keep the filtered list or re-map labels if needed.
        // Let's re-map labels to keep sequence valid
        const remapped = filtered.map((o, idx) => {
            const labels = ["A", "B", "C", "D", "E", "F", "G"];
            return { ...o, label: labels[idx] || "?" };
        });

        // Also check if correct answer is removed
        let newCorrect = q.correctAnswerLabel;
        if (q.correctAnswerLabel === label) newCorrect = null;
        else {
             // If we relabeled, we might need to adjust correct answer label... 
             // This is tricky. Simplified: just reset correct answer if we mess with options structure heavily
        }

        return {
          ...q,
          options: remapped,
          correctAnswerLabel: null // Safety reset to avoid mismatch
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const deleteQuestion = (qId: number) => {
      if(!confirm("Soruyu silmek istediğinize emin misiniz?")) return;
      const updated = exam.questions.filter(q => q.id !== qId);
      onUpdateExam({ ...exam, questions: updated });
  };

  const addQuestion = () => {
      const newQ: Question = {
          id: Math.floor(Math.random() * 100000),
          text: "",
          options: [
              { label: "A", text: "" },
              { label: "B", text: "" },
              { label: "C", text: "" },
              { label: "D", text: "" },
          ],
          correctAnswerLabel: null,
          userSelection: null
      };
      onUpdateExam({ ...exam, questions: [...exam.questions, newQ] });
      // Scroll to bottom
      setTimeout(() => {
          window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }, 100);
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-gray-900 transition-colors">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 shadow-sm px-4 py-3 flex items-center justify-between gap-4 transition-colors">
        <button onClick={onBack} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition flex-shrink-0">
          <ArrowLeft className="w-6 h-6 text-gray-600 dark:text-gray-300" />
        </button>

        <div className="flex-1 flex items-center gap-2 overflow-hidden">
          {isEditingTitle ? (
            <div className="flex items-center gap-2 w-full max-w-md">
              <input
                type="text"
                value={tempTitle}
                onChange={(e) => setTempTitle(e.target.value)}
                className="flex-1 border border-blue-300 dark:border-blue-500 rounded px-2 py-1 text-lg font-bold focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                autoFocus
                onKeyDown={(e) => e.key === 'Enter' && saveTitle()}
              />
              <button onClick={saveTitle} className="p-1 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/30 rounded">
                <CheckCircle className="w-5 h-5" />
              </button>
              <button onClick={() => { setIsEditingTitle(false); setTempTitle(exam.title); }} className="p-1 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded">
                <XCircle className="w-5 h-5" />
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2 group w-full cursor-pointer" onClick={() => setIsEditingTitle(true)}>
              <h1 className="text-lg font-bold truncate text-gray-800 dark:text-white" title="Başlığı düzenlemek için tıklayın">
                {exam.title}
              </h1>
              <Edit2 className="w-4 h-4 text-gray-400 dark:text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>
          )}
        </div>

        <div className="flex items-center gap-2">
            <button 
                onClick={() => setIsEditMode(!isEditMode)}
                className={`flex-shrink-0 flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition ${isEditMode ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300' : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`}
                title="Düzenleme Modu"
            >
                {isEditMode ? <Check className="w-4 h-4" /> : <Edit2 className="w-4 h-4" />}
                <span className="hidden sm:inline">{isEditMode ? 'Tamamla' : 'Düzenle'}</span>
            </button>

            {exam.isFinished && !isEditMode && (
            <button 
                onClick={onResetRequest}
                className="flex-shrink-0 flex items-center gap-2 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-3 py-1.5 rounded-lg text-sm font-medium hover:bg-blue-200 dark:hover:bg-blue-900/50 transition"
            >
                <RotateCcw className="w-4 h-4" />
                <span className="hidden sm:inline">Yeniden Çalış</span>
            </button>
            )}
        </div>
      </div>

      {isEditMode && (
          <div className="bg-orange-50 dark:bg-orange-900/20 px-4 py-2 text-xs sm:text-sm text-orange-800 dark:text-orange-200 text-center border-b border-orange-100 dark:border-orange-900/30">
              Düzenleme Modu: Soruları ve şıkları değiştirebilirsiniz. Doğru cevabı ayarlamak için şık harfine (A, B...) tıklayın.
          </div>
      )}

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full">
        {exam.questions.length === 0 && (
             <div className="text-center py-10 opacity-60">
                 <p className="text-xl text-gray-500 dark:text-gray-400">Bu sınavda henüz soru yok.</p>
                 {isEditMode && <p className="text-sm mt-2 text-blue-500">Aşağıdaki butonu kullanarak soru ekleyin.</p>}
             </div>
        )}

        {exam.questions.map((q, index) => (
          <div key={q.id} className="mb-8 border-b border-gray-100 dark:border-gray-800 pb-6 last:border-0 group/question">
            <div className="flex gap-3 mb-4">
              <span className="font-bold text-gray-900 dark:text-gray-100 text-lg pt-1">{index + 1}.</span>
              <div className="flex-1">
                  {isEditMode ? (
                      <textarea 
                        value={q.text}
                        onChange={(e) => handleQuestionTextChange(q.id, e.target.value)}
                        className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:outline-none min-h-[80px]"
                        placeholder="Soru metni..."
                      />
                  ) : (
                      <p className="text-gray-800 dark:text-gray-200 text-lg leading-relaxed whitespace-pre-wrap">{q.text}</p>
                  )}
              </div>
              {isEditMode && (
                  <button onClick={() => deleteQuestion(q.id)} className="self-start p-2 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded">
                      <Trash2 className="w-5 h-5" />
                  </button>
              )}
            </div>

            <div className="space-y-3 pl-2 sm:pl-8">
              {q.options.map((opt) => {
                const isSelected = q.userSelection === opt.label;
                const isCorrect = q.correctAnswerLabel === opt.label;

                // Styling Logic
                let containerClass = "w-full text-left p-3 rounded-xl border-2 transition-all duration-200 flex items-start gap-3 group relative ";
                let labelClass = "font-bold min-w-[24px] ";
                let textClass = "flex-1 ";

                if (isEditMode) {
                    containerClass += isCorrect ? "border-green-500 bg-green-50 dark:bg-green-900/10 " : "border-dashed border-gray-300 dark:border-gray-700 hover:border-blue-400 ";
                    labelClass += isCorrect ? "text-green-700 cursor-pointer hover:scale-110 transition-transform " : "text-gray-500 cursor-pointer hover:text-blue-500 ";
                    textClass += "text-gray-900 dark:text-gray-300";
                } else if (!exam.isFinished) {
                  // Active Exam State
                  if (isSelected) {
                    containerClass += "border-green-500 bg-green-50 dark:bg-green-900/20 shadow-sm";
                    labelClass += "text-green-700 dark:text-green-400";
                    textClass += "text-gray-900 dark:text-gray-100";
                  } else {
                    containerClass += "border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-500 hover:bg-gray-50 dark:hover:bg-gray-800";
                    labelClass += "text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200";
                    textClass += "text-gray-900 dark:text-gray-300";
                  }
                } else {
                  // Finished State
                  if (isCorrect) {
                    // Doğru cevap (Yeşil)
                    containerClass += "border-green-500 bg-green-100/40 dark:bg-green-900/40 shadow-sm"; 
                    textClass += "text-green-800 dark:text-green-400 font-bold";
                    labelClass += "text-green-800 dark:text-green-400 font-bold";
                  } else if (isSelected) {
                    // Yanlış işaretlenmiş (Kırmızı)
                    containerClass += "border-red-500 bg-red-50 dark:bg-red-900/20 shadow-sm";
                    textClass += "text-red-700 dark:text-red-400 font-bold";
                    labelClass += "text-red-700 dark:text-red-400 font-bold";
                  } else {
                    // Diğer şıklar (Siyah/Nötr)
                    containerClass += "border-gray-200 dark:border-gray-700 opacity-60";
                    textClass += "text-gray-900 dark:text-gray-400";
                    labelClass += "text-gray-900 dark:text-gray-400 font-medium";
                  }
                }

                return (
                    <div key={opt.label} className="relative">
                        <button
                            onClick={() => handleOptionSelect(q.id, opt.label)}
                            disabled={exam.isFinished || isEditMode}
                            className={containerClass}
                        >
                            <span 
                                className={labelClass} 
                                title={isEditMode ? "Doğru cevap olarak işaretle" : ""}
                                onClick={(e) => {
                                    if(isEditMode) {
                                        e.stopPropagation();
                                        toggleCorrectAnswer(q.id, opt.label);
                                    }
                                }}
                            >
                                {opt.label})
                            </span>

                            {isEditMode ? (
                                <input 
                                    type="text"
                                    value={opt.text}
                                    onChange={(e) => handleOptionTextChange(q.id, opt.label, e.target.value)}
                                    className="flex-1 bg-transparent border-b border-transparent focus:border-blue-500 focus:outline-none w-full"
                                    placeholder="Şık metni..."
                                    onClick={e => e.stopPropagation()}
                                />
                            ) : (
                                <span className={textClass}>{opt.text}</span>
                            )}

                            {/* Icons Logic */}
                            {!isEditMode && isSelected && !exam.isFinished && (
                                <CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-500" />
                            )}
                            {!isEditMode && exam.isFinished && isCorrect && (
                                <CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-600 dark:text-green-400" />
                            )}
                            {!isEditMode && exam.isFinished && isSelected && !isCorrect && (
                                <XCircle className="absolute right-3 top-3 w-5 h-5 text-red-500 dark:text-red-400" />
                            )}
                        </button>
                        {isEditMode && (
                            <button 
                                onClick={() => removeOption(q.id, opt.label)}
                                className="absolute right-[-30px] top-4 text-red-300 hover:text-red-500"
                            >
                                <MinusCircle className="w-5 h-5" />
                            </button>
                        )}
                    </div>
                );
              })}

              {isEditMode && (
                  <button onClick={() => addOption(q.id)} className="text-sm text-blue-500 hover:text-blue-700 flex items-center gap-1 mt-2">
                      <PlusCircle className="w-4 h-4" /> Şık Ekle
                  </button>
              )}
            </div>
          </div>
        ))}

        {isEditMode ? (
             <button 
                onClick={addQuestion}
                className="w-full py-4 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-xl text-gray-500 hover:border-blue-500 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-gray-800 transition flex flex-col items-center justify-center gap-2 mb-12"
             >
                 <PlusCircle className="w-8 h-8" />
                 <span className="font-bold">Yeni Soru Ekle</span>
             </button>
        ) : (
             !exam.isFinished && exam.questions.length > 0 && (
                <div className="mt-8 mb-12 flex justify-center">
                    <button
                    onClick={finishExam}
                    className="bg-blue-600 text-white text-lg font-bold py-4 px-12 rounded-full shadow-lg hover:bg-blue-700 hover:shadow-xl transform hover:-translate-y-1 transition-all active:scale-95 dark:shadow-blue-900/50"
                    >
                    SINAVI BİTİR
                    </button>
                </div>
            )
        )}

        {exam.isFinished && !isEditMode && (
          <div className="mt-8 mb-12 p-6 bg-gray-100 dark:bg-gray-800 rounded-xl text-center border border-gray-200 dark:border-gray-700">
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">Sınav Tamamlandı</h3>
            <p className="text-gray-600 dark:text-gray-400 mb-4">Cevaplarınızı kontrol edin. Doğru şıklar yeşil, yanlış işaretlediğiniz şıklar kırmızı ile belirtilmiştir.</p>
            <button 
              onClick={onResetRequest}
              className="bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 font-semibold py-2 px-6 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 transition"
            >
              Yeniden Çalış
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  // --- Auth State ---
  const [currentUser, setCurrentUser] = useState<string | null>(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('sinav_asistani_active_user');
    }
    return null;
  });

  const [isInitialized, setIsInitialized] = useState(false);

  // --- State ---
  const [folders, setFolders] = useState<Folder[]>([]);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null);
  const [activeExamId, setActiveExamId] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string | null>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);

  // Folder Renaming State
  const [isEditingFolderName, setIsEditingFolderName] = useState(false);
  const [tempFolderName, setTempFolderName] = useState("");
  const [editingFolderId, setEditingFolderId] = useState<string | null>(null);
  const [editFolderTempName, setEditFolderTempName] = useState("");

  // Modals State
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [examToDeleteId, setExamToDeleteId] = useState<string | null>(null);

  // Upload Report State
  const [uploadResults, setUploadResults] = useState<UploadResult[]>([]);
  const [isUploadReportOpen, setIsUploadReportOpen] = useState(false);

  // --- Persistence & Theme ---

  useEffect(() => {
    const savedTheme = localStorage.getItem('sinav_asistani_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setDarkMode(true);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      setIsInitialized(false);
      const storageKey = getStorageKey(currentUser);
      const uiKey = getUiKey(currentUser);

      const savedData = localStorage.getItem(storageKey);
      if (savedData) {
        try {
          const parsed = JSON.parse(savedData);
          setFolders(parsed || []);
        } catch (e) {
          console.error("Data load error", e);
          setFolders([]);
        }
      } else {
        setFolders([]);
      }

      const savedUi = localStorage.getItem(uiKey);
      if (savedUi) {
        try {
          const ui = JSON.parse(savedUi);
          if (ui.currentView) setCurrentView(ui.currentView);
          if (ui.activeFolderId) setActiveFolderId(ui.activeFolderId);
          if (ui.activeExamId) setActiveExamId(ui.activeExamId);
        } catch (e) {
          console.error("UI state load error", e);
        }
      }
      setIsInitialized(true);
    }
  }, [currentUser]);

  useEffect(() => {
    if (currentUser && isInitialized) {
      const storageKey = getStorageKey(currentUser);
      const uiKey = getUiKey(currentUser);
      localStorage.setItem(storageKey, JSON.stringify(folders));
      localStorage.setItem(uiKey, JSON.stringify({ currentView, activeFolderId, activeExamId }));
    }
  }, [folders, currentView, activeFolderId, activeExamId, currentUser, isInitialized]);

  // Validation
  useEffect(() => {
    if (!isInitialized) return;
    if (activeFolderId) {
        const folder = folders.find(f => f.id === activeFolderId);
        if (!folder) {
            setActiveFolderId(null);
            setCurrentView('DASHBOARD');
            return;
        }
        if (activeExamId) {
            const exam = folder.exams.find(e => e.id === activeExamId);
            if (!exam) {
                setActiveExamId(null);
                setCurrentView('FOLDER_DETAIL');
            }
        }
    }
  }, [folders, activeFolderId, activeExamId, isInitialized]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('sinav_asistani_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('sinav_asistani_theme', 'light');
    }
  }, [darkMode]);

  useEffect(() => {
    if (activeFolderId) {
      const folder = folders.find(f => f.id === activeFolderId);
      if (folder) setTempFolderName(folder.name);
    }
  }, [activeFolderId, folders]);

  // --- Actions ---

  const handleLogin = (username: string) => {
    const trimmedUser = username.trim();
    localStorage.setItem('sinav_asistani_active_user', trimmedUser);
    setCurrentUser(trimmedUser);
  };

  const handleLogout = () => {
    localStorage.removeItem('sinav_asistani_active_user');
    setCurrentUser(null);
    setFolders([]);
    setActiveFolderId(null);
    setActiveExamId(null);
    setCurrentView('DASHBOARD');
    setIsInitialized(false);
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  const createFolder = () => {
    const newId = crypto.randomUUID();
    const defaultName = "Yeni Klasör";
    const newFolder: Folder = { id: newId, name: defaultName, exams: [] };
    setFolders(prev => [...prev, newFolder]);
    setEditingFolderId(newId);
    setEditFolderTempName(defaultName);
  };

  const deleteFolder = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Bu klasörü ve içindeki tüm sınavları silmek istediğinize emin misiniz?")) {
      setFolders(folders.filter(f => f.id !== id));
      if (activeFolderId === id) {
        setActiveFolderId(null);
        setCurrentView('DASHBOARD');
      }
    }
  };

  const startEditingFolder = (e: React.MouseEvent, folder: Folder) => {
    e.stopPropagation();
    setEditingFolderId(folder.id);
    setEditFolderTempName(folder.name);
  };

  const saveFolderEdit = (e: React.MouseEvent | React.FormEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    if (editingFolderId && editFolderTempName.trim()) {
      setFolders(prev => prev.map(f => f.id === editingFolderId ? { ...f, name: editFolderTempName } : f));
      setEditingFolderId(null);
    } else {
      setEditingFolderId(null);
    }
  };

  const cancelFolderEdit = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    setEditingFolderId(null);
  };

  const saveFolderNameDetail = () => {
    if (activeFolderId && tempFolderName.trim()) {
      setFolders(prev => prev.map(f => f.id === activeFolderId ? { ...f, name: tempFolderName } : f));
      setIsEditingFolderName(false);
    } else {
      const folder = folders.find(f => f.id === activeFolderId);
      if (folder) setTempFolderName(folder.name);
      setIsEditingFolderName(false);
    }
  };

  // --- File Upload Logic ---

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>, targetFolderId?: string) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    let folderId = targetFolderId || activeFolderId;
    let newFolderId = "";

    // Implicit folder creation
    if (!folderId) {
      newFolderId = crypto.randomUUID();
      folderId = newFolderId;
      const newFolder: Folder = { id: newFolderId, name: "Genel", exams: [] };
      setFolders(prev => [...prev, newFolder]);
    }

    setCurrentView('LOADING');
    setUploadResults([]); // Clear previous results

    const results: UploadResult[] = [];
    const processedExams: { folderId: string, exam: Exam }[] = [];

    // Process all files
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setLoadingMessage(`Dosya işleniyor (${i + 1}/${files.length}): ${file.name}`);

      try {
        const mimeType = getMimeType(file);
        let data = '';
        if (mimeType.startsWith('text/')) {
          data = await fileToText(file);
        } else {
          data = await fileToBase64(file);
        }

        const parsedData = await parseExamFile(data, mimeType);

        // Check if parsing yielded no questions - treat as error/warning
        if (parsedData.questions.length === 0) {
            results.push({ fileName: file.name, status: 'error', message: "Soru bulunamadı veya dosya okunamadı." });
        } else {
            const newExam: Exam = {
                id: crypto.randomUUID(),
                title: parsedData.title,
                dateCreated: new Date().toISOString(),
                questions: parsedData.questions,
                isFinished: false
            };
            processedExams.push({ folderId: folderId!, exam: newExam });
            results.push({ fileName: file.name, status: 'success' });
        }

      } catch (error) {
        console.error(`Error processing file ${file.name}:`, error);
        results.push({ fileName: file.name, status: 'error', message: "İşlem hatası" });
      }
    }

    // Batch update state
    if (processedExams.length > 0) {
        setFolders(prev => prev.map(f => {
            const folderExamsToAdd = processedExams.filter(pe => pe.folderId === f.id).map(pe => pe.exam);
            if (folderExamsToAdd.length > 0) {
                return { ...f, exams: [...f.exams, ...folderExamsToAdd] };
            }
            return f;
        }));
    }

    setUploadResults(results);
    setLoadingMessage(null);

    // Navigation logic
    const hasErrors = results.some(r => r.status === 'error');
    const successCount = results.filter(r => r.status === 'success').length;

    // If there are errors, or mix of success/errors, show report
    if (hasErrors) {
        if (!activeFolderId && newFolderId) setActiveFolderId(newFolderId);
        setCurrentView('FOLDER_DETAIL'); // Go to folder view behind modal
        setIsUploadReportOpen(true);
    } else {
        // All success
        if (!activeFolderId && newFolderId) setActiveFolderId(newFolderId);

        // If single file, go to it
        if (files.length === 1 && processedExams.length === 1) {
            setActiveExamId(processedExams[0].exam.id);
            setCurrentView('EXAM_TAKER');
        } else {
            setCurrentView('FOLDER_DETAIL');
        }
    }
  };

  const handleManualCreate = (fileName: string) => {
      // Create empty exam
      if (!activeFolderId) return;

      const newExam: Exam = {
          id: crypto.randomUUID(),
          title: fileName,
          dateCreated: new Date().toISOString(),
          questions: [],
          isFinished: false
      };

      setFolders(prev => prev.map(f => {
          if (f.id === activeFolderId) {
              return { ...f, exams: [...f.exams, newExam] };
          }
          return f;
      }));

      setIsUploadReportOpen(false);
      setActiveExamId(newExam.id);
      setCurrentView('EXAM_TAKER');
      // The ExamTaker component will show empty state or auto-enable edit mode conceptually
  };

  const updateExamInState = (updatedExam: Exam) => {
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return {
          ...f,
          exams: f.exams.map(e => e.id === updatedExam.id ? updatedExam : e)
        };
      }
      return f;
    }));
  };

  // --- Reset & Archive Logic ---

  const handleResetRequest = () => setIsResetModalOpen(true);

  const handleArchiveAndReset = () => {
    if (!activeFolderId || !activeExamId) return;
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        const currentExam = f.exams.find(e => e.id === activeExamId);
        if (!currentExam) return f;
        const dateStr = new Date().toLocaleDateString('tr-TR', { hour: '2-digit', minute: '2-digit' });
        const archivedExam: Exam = {
          ...JSON.parse(JSON.stringify(currentExam)),
          id: crypto.randomUUID(),
          title: `${currentExam.title} (Tamamlandı - ${dateStr})`,
          isFinished: true,
        };
        const resetExam: Exam = {
          ...currentExam,
          isFinished: false,
          questions: currentExam.questions.map(q => ({ ...q, userSelection: null }))
        };
        return { ...f, exams: [...f.exams.filter(e => e.id !== activeExamId), archivedExam, resetExam] };
      }
      return f;
    }));
    setIsResetModalOpen(false);
  };

  const handleJustReset = () => {
    if (!activeFolderId || !activeExamId) return;
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return { ...f, exams: f.exams.map(e => e.id === activeExamId ? { ...e, isFinished: false, questions: e.questions.map(q => ({ ...q, userSelection: null })) } : e) };
      }
      return f;
    }));
    setIsResetModalOpen(false);
  };

  // --- Delete Exam ---

  const requestDeleteExam = (e: React.MouseEvent, examId: string) => {
    e.stopPropagation();
    setExamToDeleteId(examId);
  };

  const confirmDeleteExam = () => {
    if (!examToDeleteId) return;
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return { ...f, exams: f.exams.filter(ex => ex.id !== examToDeleteId) };
      }
      return f;
    }));
    setExamToDeleteId(null);
  };

  // --- Rendering Helpers ---

  // ... (renderDashboard and renderFolderDetail kept largely the same, minor updates)
  const renderDashboard = () => (
    <div className="p-6 max-w-5xl mx-auto w-full flex flex-col h-full">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Sınav Kitaplığım</h1>
        <button onClick={createFolder} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg font-medium transition shadow-md shadow-blue-500/20"><Plus className="w-5 h-5" /><span>Yeni Klasör</span></button>
      </div>
      {folders.length === 0 ? (
        <div className="flex-1 flex flex-col items-center justify-center -mt-20">
          <div className="bg-white dark:bg-gray-800 p-10 rounded-3xl shadow-xl border border-blue-100 dark:border-gray-700 text-center max-w-lg w-full transform hover:scale-[1.01] transition-all">
            <div className="bg-blue-50 dark:bg-blue-900/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6"><Upload className="w-10 h-10 text-blue-600 dark:text-blue-400" /></div>
            <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-3">Sınav Asistanına Hoşgeldiniz</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-8">Sınav hazırlığına başlamak için dosyanızı yükleyin. Sorular otomatik olarak taranıp test haline getirilecektir.</p>
            <label className="block w-full cursor-pointer">
              <div className="bg-blue-600 hover:bg-blue-700 text-white text-lg font-bold py-4 px-6 rounded-xl shadow-lg transition flex items-center justify-center gap-3 shadow-blue-500/30"><Upload className="w-6 h-6" />Dosyayı Yükle</div>
              <input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.bmp,.ai,.xlsx,.htm,.html,.txt,.docx" onChange={(e) => handleFileUpload(e)} className="hidden" />
            </label>
            <p className="text-xs text-gray-400 dark:text-gray-500 mt-4">Desteklenen formatlar: PDF, JPG, PNG, AI, BMP, XLSX, DOCX, TXT, HTML</p>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {folders.map(folder => (
            <div key={folder.id} onClick={() => { setActiveFolderId(folder.id); setCurrentView('FOLDER_DETAIL'); }} className="group bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 hover:shadow-lg hover:border-blue-200 dark:hover:border-blue-500/50 transition-all cursor-pointer relative">
              <div className="flex items-start justify-between mb-4">
                <div className="p-3 bg-blue-50 dark:bg-blue-900/30 rounded-xl group-hover:bg-blue-100 dark:group-hover:bg-blue-900/50 transition"><FolderIcon className="w-8 h-8 text-blue-600 dark:text-blue-400" /></div>
                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={(e) => startEditingFolder(e, folder)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-500 dark:text-gray-400"><Edit2 className="w-4 h-4" /></button>
                  <button onClick={(e) => deleteFolder(e, folder.id)} className="p-1.5 hover:bg-red-50 dark:hover:bg-red-900/30 rounded text-red-500 dark:text-red-400"><Trash2 className="w-4 h-4" /></button>
                </div>
              </div>
              {editingFolderId === folder.id ? (
                <div className="mb-1 flex items-center gap-2" onClick={e => e.stopPropagation()}>
                    <input type="text" value={editFolderTempName} onChange={(e) => setEditFolderTempName(e.target.value)} className="w-full border border-blue-400 rounded px-2 py-1 text-lg font-bold bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500" autoFocus onKeyDown={(e) => { if(e.key === 'Enter') saveFolderEdit(e); if(e.key === 'Escape') cancelFolderEdit(e); }} onClick={e => e.stopPropagation()} />
                    <button onClick={saveFolderEdit} className="p-1 text-green-600 hover:bg-green-100 dark:hover:bg-green-900/30 rounded flex-shrink-0"><CheckCircle className="w-5 h-5" /></button>
                    <button onClick={cancelFolderEdit} className="p-1 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/30 rounded flex-shrink-0"><XCircle className="w-5 h-5" /></button>
                </div>
              ) : <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-1 truncate">{folder.name}</h3>}
              <p className="text-gray-500 dark:text-gray-400 text-sm">{folder.exams.length} Sınav</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderFolderDetail = () => {
    const activeFolder = folders.find(f => f.id === activeFolderId);
    if (!activeFolder) return null;
    return (
      <div className="p-6 max-w-5xl mx-auto w-full h-full flex flex-col">
        <div className="flex items-center gap-4 mb-8">
          <button onClick={() => { setActiveFolderId(null); setCurrentView('DASHBOARD'); setIsEditingFolderName(false); }} className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition flex-shrink-0"><ArrowLeft className="w-6 h-6 text-gray-700 dark:text-gray-200" /></button>
          <div className="flex-1 overflow-hidden">
            {isEditingFolderName ? (
              <div className="flex items-center gap-2 max-w-md">
                <input type="text" value={tempFolderName} onChange={(e) => setTempFolderName(e.target.value)} className="flex-1 border border-blue-300 dark:border-blue-500 rounded px-2 py-1 text-2xl font-bold focus:outline-none focus:ring-2 focus:ring-blue-500 bg-transparent text-gray-900 dark:text-white" autoFocus onKeyDown={(e) => e.key === 'Enter' && saveFolderNameDetail()} />
                <button onClick={saveFolderNameDetail} className="p-1 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/30 rounded"><CheckCircle className="w-6 h-6" /></button>
                <button onClick={() => { setIsEditingFolderName(false); setTempFolderName(activeFolder.name); }} className="p-1 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded"><XCircle className="w-6 h-6" /></button>
              </div>
            ) : (
              <div className="flex items-center gap-3 group cursor-pointer" onClick={() => { setIsEditingFolderName(true); setTempFolderName(activeFolder.name); }}><h1 className="text-2xl font-bold text-gray-900 dark:text-white">{activeFolder.name}</h1><Edit2 className="w-4 h-4 text-gray-400 dark:text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity" /></div>
            )}
            <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">Sınav Listesi</p>
          </div>
          <label className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg font-medium transition shadow-md cursor-pointer flex-shrink-0 shadow-blue-500/20"><Upload className="w-5 h-5" /><span>Dosyayı Yükle</span><input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.bmp,.ai,.xlsx,.htm,.html,.txt,.docx" onChange={handleFileUpload} className="hidden" /></label>
        </div>
        {activeFolder.exams.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center opacity-60">
            <div className="w-20 h-20 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4"><FileText className="w-10 h-10 text-gray-400 dark:text-gray-500" /></div>
            <h3 className="text-xl font-medium text-gray-700 dark:text-gray-300">Bu klasör henüz boş</h3>
            <p className="max-w-md mt-2 text-gray-500 dark:text-gray-400">Yukarıdaki "Dosyayı Yükle" butonuna basarak soru kitapçıklarınızı ekleyebilirsiniz.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4">
            {activeFolder.exams.map(exam => (
              <div key={exam.id} onClick={() => { setActiveExamId(exam.id); setCurrentView('EXAM_TAKER'); }} className="bg-white dark:bg-gray-800 p-5 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm hover:shadow-md hover:border-blue-300 dark:hover:border-blue-500 transition cursor-pointer flex items-center justify-between group">
                <div className="flex items-center gap-4">
                  <div className={`w-12 h-12 rounded-lg flex items-center justify-center text-lg font-bold transition-colors ${exam.isFinished ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-300 group-hover:bg-blue-50 dark:group-hover:bg-blue-900/30 group-hover:text-blue-600 dark:group-hover:text-blue-400'}`}>{exam.isFinished ? '✓' : '?'}</div>
                  <div><h3 className="font-bold text-gray-800 dark:text-gray-100 text-lg group-hover:text-blue-700 dark:group-hover:text-blue-400 transition-colors">{exam.title}</h3><p className="text-gray-500 dark:text-gray-400 text-sm">{new Date(exam.dateCreated).toLocaleDateString('tr-TR')} • {exam.questions.length} Soru</p></div>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={(e) => requestDeleteExam(e, exam.id)} className="p-2 text-gray-400 dark:text-gray-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-full transition" title="Sınavı Sil"><Trash2 className="w-5 h-5" /></button>
                  <div className="text-gray-400 dark:text-gray-500 group-hover:translate-x-1 transition-transform"><ArrowLeft className="w-5 h-5 rotate-180" /></div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  // --- Main Render ---

  if (!currentUser) {
    return (
      <>
       <div className="absolute top-4 right-4 z-50">
           <button onClick={toggleDarkMode} className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors" title={darkMode ? "Aydınlık Mod" : "Karanlık Mod"}>{darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}</button>
        </div>
        <LoginScreen onLogin={handleLogin} />
      </>
    );
  }

  if (currentView === 'LOADING') {
    return <LoadingScreen message={loadingMessage || undefined} />;
  }

  const examToDeleteTitle = examToDeleteId ? folders.find(f => f.id === activeFolderId)?.exams.find(e => e.id === examToDeleteId)?.title : "";

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex flex-col h-screen overflow-hidden relative transition-colors duration-200">
      <ResetModal isOpen={isResetModalOpen} onClose={() => setIsResetModalOpen(false)} onSaveAndReset={handleArchiveAndReset} onJustReset={handleJustReset} />
      <DeleteModal isOpen={!!examToDeleteId} onClose={() => setExamToDeleteId(null)} onConfirm={confirmDeleteExam} itemName={examToDeleteTitle || "Sınav"} />
      <UploadReportModal results={uploadResults} isOpen={isUploadReportOpen} onClose={() => setIsUploadReportOpen(false)} onCreateManually={handleManualCreate} />

      {currentView !== 'EXAM_TAKER' && (
        <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 py-3 px-6 shadow-sm flex items-center justify-between flex-shrink-0 transition-colors">
          <div className="flex items-center gap-2"><div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-lg flex items-center justify-center text-white font-bold shadow-sm shadow-blue-500/30">A</div><span className="font-bold text-gray-800 dark:text-white text-lg tracking-tight">Sınav Asistanı</span></div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 mr-2"><div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-700 dark:text-blue-300 font-bold text-sm">{currentUser.substring(0, 2).toUpperCase()}</div><span className="text-sm font-medium text-gray-700 dark:text-gray-300 hidden sm:block">{currentUser}</span></div>
            <button onClick={toggleDarkMode} className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors" title={darkMode ? "Aydınlık Mod" : "Karanlık Mod"}>{darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}</button>
            <button onClick={handleLogout} className="p-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors" title="Çıkış Yap"><LogOut className="w-5 h-5" /></button>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-y-auto">
        {currentView === 'DASHBOARD' && renderDashboard()}
        {currentView === 'FOLDER_DETAIL' && renderFolderDetail()}
        {currentView === 'EXAM_TAKER' && (() => {
          const activeExam = folders.find(f => f.id === activeFolderId)?.exams.find(e => e.id === activeExamId);
          if (!activeExam) return <div>Sınav bulunamadı</div>;

          return (
            <div className="h-full relative flex flex-col">
               <div className="absolute top-3 right-4 z-40 flex gap-2">
                  <button onClick={toggleDarkMode} className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors shadow-sm border border-gray-200 dark:border-gray-600" title={darkMode ? "Aydınlık Mod" : "Karanlık Mod"}>{darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}</button>
               </div>
              <ExamTaker exam={activeExam} onUpdateExam={updateExamInState} onBack={() => setCurrentView('FOLDER_DETAIL')} onResetRequest={handleResetRequest} />
            </div>
          );
        })()}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Folder, Exam, Question, AppView, Option } from './types';
import { fileToBase64, fileToText, getMimeType } from './services/fileUtils';
import { parseExamFile } from './services/geminiService';
import LoadingScreen from './components/LoadingScreen';
import { 
  ArrowLeft, Folder as FolderIcon, Plus, FileText, Trash2, RotateCcw, 
  CheckCircle, Upload, XCircle, Edit2, Save, X, AlertTriangle, Moon, 
  Sun, LogOut, User, Lock, Key, Eye, EyeOff, UserPlus, LogIn, 
  AlertCircle, FileWarning, PlusCircle, MinusCircle, Check,
  Cloud, CloudOff, RefreshCw
} from 'lucide-react';

// --- Helper Functions for Persistence ---

// Generates a consistent, case-insensitive key for storage to prevent data loss due to capitalization
const normalizeUsername = (username: string) => username.trim().toLocaleLowerCase('tr-TR');
const getStorageKey = (username: string) => `sinav_asistani_data_${normalizeUsername(username)}`;
const getUiKey = (username: string) => `sinav_asistani_ui_${normalizeUsername(username)}`;
const USER_REGISTRY_KEY = 'sinav_asistani_users_registry';

// --- Types for Upload Handling ---
interface UploadResult {
  fileName: string;
  status: 'success' | 'error';
  message?: string;
}

// --- Components defined within App to share state logic easily ---

// 0. Login & Register Screen Component
interface LoginScreenProps {
  onLogin: (username: string) => void;
}

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [suggestions, setSuggestions] = useState<string[]>([]);

  // Clear errors when switching modes
  useEffect(() => {
    setError('');
    setSuggestions([]);
    setPassword('');
  }, [isRegistering]);

  const generateSuggestions = (baseName: string, registry: any) => {
    const list: string[] = [];
    const now = new Date();
    const seeds = [
      `${baseName}${now.getFullYear()}`,
      `${baseName}_${Math.floor(Math.random() * 100)}`,
      `${baseName}123`,
      `${baseName}.${now.getDate()}`,
      `By${baseName}`
    ];

    seeds.forEach(seed => {
      const key = normalizeUsername(seed);
      if (!registry[key]) {
        list.push(seed);
      }
    });
    return list.slice(0, 3);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuggestions([]);

    const trimmedUser = username.trim();
    const userKey = normalizeUsername(trimmedUser);

    if (!trimmedUser) {
      setError('Lütfen bir kullanıcı adı giriniz.');
      return;
    }
    if (trimmedUser.length < 3) {
      setError('Kullanıcı adı en az 3 karakter olmalıdır.');
      return;
    }
    if (!password || password.length < 4) {
      setError('Şifre en az 4 karakter olmalıdır.');
      return;
    }

    // Load User Registry
    const registryRaw = localStorage.getItem(USER_REGISTRY_KEY);
    const registry = registryRaw ? JSON.parse(registryRaw) : {};

    if (isRegistering) {
      // REGISTER LOGIC
      if (registry[userKey]) {
        setError('Bu kullanıcı adı maalesef dolu.');
        const alts = generateSuggestions(trimmedUser, registry);
        setSuggestions(alts);
        return;
      }

      // Create new user
      registry[userKey] = {
        password: password, // In a real app, hash this!
        createdAt: new Date().toISOString()
      };
      localStorage.setItem(USER_REGISTRY_KEY, JSON.stringify(registry));

      // Auto login after register
      onLogin(trimmedUser);
    } else {
      // LOGIN LOGIC
      const userRecord = registry[userKey];

      if (!userRecord) {
        setError('Kullanıcı bulunamadı. Lütfen önce kayıt olun.');
        return;
      }

      if (userRecord.password !== password) {
        setError('Hatalı şifre.');
        return;
      }

      // Success
      onLogin(trimmedUser);
    }
  };

  const handleSuggestionClick = (sug: string) => {
    setUsername(sug);
    setSuggestions([]);
    setError('');
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex flex-col items-center justify-center p-4 transition-colors duration-200">
      <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-8 border border-gray-100 dark:border-gray-700">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl flex items-center justify-center text-white font-bold text-3xl shadow-lg shadow-blue-500/30 mx-auto mb-4">
            A
          </div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Sınav Asistanı</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-2">
            {isRegistering ? 'Yeni hesap oluşturun' : 'Hesabınıza giriş yapın'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              Kullanıcı Adı
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <User className="h-5 w-5 text-gray-400" />
              </div>
              <input
                type="text"
                value={username}
                onChange={(e) => {
                  setUsername(e.target.value);
                  setError('');
                  setSuggestions([]);
                }}
                className="block w-full pl-10 pr-3 py-3 border border-gray-300 dark:border-gray-600 rounded-xl bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-colors"
                placeholder="Adınız"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              Şifre
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Lock className="h-5 w-5 text-gray-400" />
              </div>
              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setError('');
                }}
                className="block w-full pl-10 pr-10 py-3 border border-gray-300 dark:border-gray-600 rounded-xl bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-colors"
                placeholder="••••••"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
              </button>
            </div>
          </div>

          {error && (
            <div className="p-3 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 rounded-lg">
              <p className="text-sm text-red-600 dark:text-red-400 flex items-center gap-2">
                <AlertTriangle className="w-4 h-4" />
                {error}
              </p>
            </div>
          )}

          {suggestions.length > 0 && (
            <div className="animate-in slide-in-from-top-2 duration-300">
              <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">Şunu deneyebilirsiniz:</p>
              <div className="flex flex-wrap gap-2">
                {suggestions.map((sug) => (
                  <button
                    key={sug}
                    type="button"
                    onClick={() => handleSuggestionClick(sug)}
                    className="bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-3 py-1 rounded-full text-sm font-medium hover:bg-blue-100 dark:hover:bg-blue-900/50 transition border border-blue-200 dark:border-blue-800"
                  >
                    {sug}
                  </button>
                ))}
              </div>
            </div>
          )}

          <button
            type="submit"
            className="w-full flex justify-center py-3.5 px-4 border border-transparent rounded-xl shadow-lg text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-all transform active:scale-95 mt-4"
          >
            {isRegistering ? (
                <span className="flex items-center gap-2"><UserPlus className="w-5 h-5"/> Kayıt Ol</span>
            ) : (
                <span className="flex items-center gap-2"><LogIn className="w-5 h-5"/> Giriş Yap</span>
            )}
          </button>
        </form>

        <div className="mt-6 pt-6 border-t border-gray-100 dark:border-gray-700 text-center">
          <button
            onClick={() => setIsRegistering(!isRegistering)}
            className="text-sm font-medium text-blue-600 hover:text-blue-500 dark:text-blue-400 dark:hover:text-blue-300 transition-colors"
          >
            {isRegistering 
              ? "Zaten bir hesabınız var mı? Giriş Yapın" 
              : "Hesabınız yok mu? Hemen Kayıt Olun"}
          </button>
        </div>
      </div>
    </div>
  );
};

