// 3. Statistics View
interface StatisticsViewProps {
  folders: Folder[];
  onBack: () => void;
}

const StatisticsView: React.FC<StatisticsViewProps> = ({ folders, onBack }) => {
  // --- Calculation Logic ---
  const allExams = folders.flatMap(f => f.exams);
  const totalExams = allExams.length;

  let totalQuestions = 0;
  let totalAttempted = 0;
  let totalCorrect = 0;
  let totalIncorrect = 0;

  allExams.forEach(exam => {
    exam.questions.forEach(q => {
      totalQuestions++;
      if (q.userSelection) {
        totalAttempted++;
        if (q.correctAnswerLabel && q.userSelection === q.correctAnswerLabel) {
          totalCorrect++;
        } else if (q.correctAnswerLabel) {
           totalIncorrect++;
        }
      }
    });
  });

  const accuracy = totalAttempted > 0 ? Math.round((totalCorrect / totalAttempted) * 100) : 0;
  const completion = totalQuestions > 0 ? Math.round((totalAttempted / totalQuestions) * 100) : 0;
  const totalEmpty = totalQuestions - totalAttempted;

  // Folder Performance (Topic Proxy)
  const folderStats = folders.map(f => {
      let fCorrect = 0;
      let fAttempted = 0;
      f.exams.forEach(e => {
          e.questions.forEach(q => {
              if(q.userSelection) {
                  fAttempted++;
                  if(q.correctAnswerLabel && q.userSelection === q.correctAnswerLabel) fCorrect++;
              }
          });
      });
      const fAcc = fAttempted > 0 ? Math.round((fCorrect / fAttempted) * 100) : 0;
      return { id: f.id, name: f.name, accuracy: fAcc, attempted: fAttempted };
  }).filter(f => f.attempted > 0).sort((a,b) => b.accuracy - a.accuracy);

  // Weakest Exams (Min 5 questions attempted to be significant)
  const weakestExams = allExams.map(e => {
      let eCorrect = 0;
      let eAttempted = 0;
      e.questions.forEach(q => {
          if(q.userSelection) {
              eAttempted++;
              if(q.correctAnswerLabel && q.userSelection === q.correctAnswerLabel) eCorrect++;
          }
      });
      const eAcc = eAttempted > 0 ? Math.round((eCorrect / eAttempted) * 100) : 0;
      return { id: e.id, title: e.title, accuracy: eAcc, attempted: eAttempted };
  }).filter(e => e.attempted >= 5).sort((a,b) => a.accuracy - b.accuracy).slice(0, 5);

  return (
      <div className="p-6 max-w-5xl mx-auto w-full flex flex-col h-full overflow-y-auto">
          {/* Header */}
          <div className="flex items-center gap-4 mb-8">
            <button onClick={onBack} className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition flex-shrink-0">
                <ArrowLeft className="w-6 h-6 text-gray-700 dark:text-gray-200" />
            </button>
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                    <BarChart2 className="w-7 h-7 text-blue-600 dark:text-blue-400" />
                    İstatistikler
                </h1>
                <p className="text-gray-500 dark:text-gray-400 text-sm">Genel durum ve performans analizi</p>
            </div>
          </div>

          {/* Key Metrics Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
              <div className="bg-white dark:bg-gray-800 p-5 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm flex flex-col justify-between">
                  <div className="flex justify-between items-start mb-2">
                      <p className="text-gray-500 dark:text-gray-400 font-medium">Genel Başarı</p>
                      <div className="p-2 bg-green-100 dark:bg-green-900/30 rounded-lg text-green-600 dark:text-green-400">
                          <TrendingUp className="w-5 h-5" />
                      </div>
                  </div>
                  <h3 className="text-3xl font-bold text-gray-900 dark:text-white">%{accuracy}</h3>
                  <p className="text-xs text-gray-400 mt-1">Cevaplanan sorular üzerinden</p>
              </div>

              <div className="bg-white dark:bg-gray-800 p-5 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm flex flex-col justify-between">
                  <div className="flex justify-between items-start mb-2">
                      <p className="text-gray-500 dark:text-gray-400 font-medium">Tamamlanma</p>
                      <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                          <Activity className="w-5 h-5" />
                      </div>
                  </div>
                  <h3 className="text-3xl font-bold text-gray-900 dark:text-white">%{completion}</h3>
                  <p className="text-xs text-gray-400 mt-1">{totalAttempted} / {totalQuestions} soru çözüldü</p>
              </div>

               <div className="bg-white dark:bg-gray-800 p-5 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm flex flex-col justify-between">
                  <div className="flex justify-between items-start mb-2">
                      <p className="text-gray-500 dark:text-gray-400 font-medium">Toplam Soru</p>
                      <div className="p-2 bg-purple-100 dark:bg-purple-900/30 rounded-lg text-purple-600 dark:text-purple-400">
                          <CheckCircle className="w-5 h-5" />
                      </div>
                  </div>
                  <h3 className="text-3xl font-bold text-gray-900 dark:text-white">{totalQuestions}</h3>
              </div>

              <div className="bg-white dark:bg-gray-800 p-5 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm flex flex-col justify-between">
                  <div className="flex justify-between items-start mb-2">
                      <p className="text-gray-500 dark:text-gray-400 font-medium">Sınav Sayısı</p>
                      <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-lg text-orange-600 dark:text-orange-400">
                          <FileText className="w-5 h-5" />
                      </div>
                  </div>
                  <h3 className="text-3xl font-bold text-gray-900 dark:text-white">{totalExams}</h3>
              </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
              {/* Question Distribution Bar */}
              <div className="bg-white dark:bg-gray-800 p-6 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm">
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
                      <PieChart className="w-5 h-5 text-gray-500" />
                      Soru Dağılımı
                  </h3>

                  {totalQuestions === 0 ? (
                      <div className="text-center py-8 text-gray-400">Veri yok</div>
                  ) : (
                      <div className="space-y-6">
                           <div className="h-4 w-full bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden flex">
                               <div style={{ width: `${(totalCorrect/totalQuestions)*100}%` }} className="h-full bg-green-500" />
                               <div style={{ width: `${(totalIncorrect/totalQuestions)*100}%` }} className="h-full bg-red-500" />
                               <div style={{ width: `${(totalEmpty/totalQuestions)*100}%` }} className="h-full bg-gray-300 dark:bg-gray-600" />
                           </div>
                           <div className="flex justify-between text-sm">
                               <div className="flex items-center gap-2">
                                   <div className="w-3 h-3 rounded-full bg-green-500" />
                                   <span className="text-gray-600 dark:text-gray-300">Doğru: {totalCorrect}</span>
                               </div>
                                <div className="flex items-center gap-2">
                                   <div className="w-3 h-3 rounded-full bg-red-500" />
                                   <span className="text-gray-600 dark:text-gray-300">Yanlış: {totalIncorrect}</span>
                               </div>
                                <div className="flex items-center gap-2">
                                   <div className="w-3 h-3 rounded-full bg-gray-300 dark:bg-gray-600" />
                                   <span className="text-gray-600 dark:text-gray-300">Boş: {totalEmpty}</span>
                               </div>
                           </div>
                      </div>
                  )}
              </div>

              {/* Weakest Areas */}
              <div className="bg-white dark:bg-gray-800 p-6 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm">
                  <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                      <AlertTriangle className="w-5 h-5 text-orange-500" />
                      Geliştirilmesi Gereken Sınavlar
                  </h3>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mb-4">En düşük başarı oranına sahip, en az 5 soru çözdüğünüz sınavlar.</p>

                  {weakestExams.length === 0 ? (
                      <div className="text-center py-8 text-gray-400">Yeterli veri yok</div>
                  ) : (
                      <div className="space-y-3">
                          {weakestExams.map(ex => (
                              <div key={ex.id} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                                  <span className="font-medium text-gray-800 dark:text-gray-200 truncate flex-1 pr-4">{ex.title}</span>
                                  <div className="flex items-center gap-2">
                                      <span className="text-red-500 font-bold">%{ex.accuracy}</span>
                                      <span className="text-xs text-gray-400">({ex.attempted} soru)</span>
                                  </div>
                              </div>
                          ))}
                      </div>
                  )}
              </div>
          </div>

           {/* Folder Performance (Topics) */}
           <div className="bg-white dark:bg-gray-800 p-6 rounded-xl border border-gray-100 dark:border-gray-700 shadow-sm mb-8">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-6 flex items-center gap-2">
                  <FolderIcon className="w-5 h-5 text-blue-500" />
                  Klasör Bazlı Performans (Konular)
              </h3>
               {folderStats.length === 0 ? (
                  <div className="text-center py-8 text-gray-400">Veri yok</div>
               ) : (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
                       {folderStats.map(f => (
                           <div key={f.id} className="mb-2">
                               <div className="flex justify-between mb-1">
                                   <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{f.name}</span>
                                   <span className="text-sm font-bold text-blue-600 dark:text-blue-400">%{f.accuracy}</span>
                               </div>
                               <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2.5">
                                   <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${f.accuracy}%` }}></div>
