// 4. Exam Taker Component
interface ExamTakerProps {
  exam: Exam;
  onUpdateExam: (updatedExam: Exam) => void;
  onBack: () => void;
  onResetRequest: () => void;
  isSaving: boolean;
  lastSaved: Date | null;
  hasUnsavedChanges: boolean;
}

const ExamTaker: React.FC<ExamTakerProps> = ({ exam, onUpdateExam, onBack, onResetRequest, isSaving, lastSaved, hasUnsavedChanges }) => {
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [tempTitle, setTempTitle] = useState(exam.title);
  const [isEditMode, setIsEditMode] = useState(false);

  // Sync temp title if exam changes externally
  useEffect(() => {
    setTempTitle(exam.title);
  }, [exam.title]);

  const handleOptionSelect = (questionId: number, label: string) => {
    if (isEditMode) return; // Disable answering in edit mode
    if (exam.isFinished) return;

    const updatedQuestions = exam.questions.map(q => {
      if (q.id === questionId) {
        // Toggle logic
        return { ...q, userSelection: q.userSelection === label ? null : label };
      }
      return q;
    });

    onUpdateExam({ ...exam, questions: updatedQuestions });
  };

  const finishExam = () => {
    onUpdateExam({ ...exam, isFinished: true });
    setTimeout(() => {
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    }, 100);
  };

  const saveTitle = () => {
    if (tempTitle.trim()) {
      onUpdateExam({ ...exam, title: tempTitle });
    } else {
      setTempTitle(exam.title); // Revert if empty
    }
    setIsEditingTitle(false);
  };

  // --- EDIT MODE HANDLERS ---

  const handleQuestionTextChange = (qId: number, text: string) => {
    const updated = exam.questions.map(q => q.id === qId ? { ...q, text } : q);
    onUpdateExam({ ...exam, questions: updated });
  };

  const handleOptionTextChange = (qId: number, optLabel: string, text: string) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        return {
          ...q,
          options: q.options.map(o => o.label === optLabel ? { ...o, text } : o)
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const toggleCorrectAnswer = (qId: number, label: string) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        // If clicking the current correct answer, unset it. Else set it.
        return { 
          ...q, 
          correctAnswerLabel: q.correctAnswerLabel === label ? null : label 
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const addOption = (qId: number) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        const labels = ["A", "B", "C", "D", "E", "F", "G"];
        const nextLabel = labels[q.options.length] || "X";
        return {
          ...q,
          options: [...q.options, { label: nextLabel, text: "" }]
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const removeOption = (qId: number, label: string) => {
    const updated = exam.questions.map(q => {
      if (q.id === qId) {
        const filtered = q.options.filter(o => o.label !== label);
        // Let's re-map labels to keep sequence valid
        const remapped = filtered.map((o, idx) => {
            const labels = ["A", "B", "C", "D", "E", "F", "G"];
            return { ...o, label: labels[idx] || "?" };
        });

        return {
          ...q,
          options: remapped,
          correctAnswerLabel: null // Safety reset to avoid mismatch
        };
      }
      return q;
    });
    onUpdateExam({ ...exam, questions: updated });
  };

  const deleteQuestion = (qId: number) => {
      if(!confirm("Soruyu silmek istediğinize emin misiniz?")) return;
      const updated = exam.questions.filter(q => q.id !== qId);
      onUpdateExam({ ...exam, questions: updated });
  };

  const addQuestion = () => {
      const newQ: Question = {
          id: Math.floor(Math.random() * 100000),
          text: "",
          options: [
              { label: "A", text: "" },
              { label: "B", text: "" },
              { label: "C", text: "" },
              { label: "D", text: "" },
          ],
          correctAnswerLabel: null,
          userSelection: null
      };
      onUpdateExam({ ...exam, questions: [...exam.questions, newQ] });
      // Scroll to bottom
      setTimeout(() => {
          window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }, 100);
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-gray-900 transition-colors">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 shadow-sm px-4 py-3 flex items-center justify-between gap-4 transition-colors">
        <div className="flex items-center gap-2">
            <button onClick={onBack} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition flex-shrink-0">
            <ArrowLeft className="w-6 h-6 text-gray-600 dark:text-gray-300" />
            </button>
            <div className="hidden sm:flex flex-col">
                <div className="flex items-center gap-1.5 text-xs">
                    {isSaving ? (
                        <span className="flex items-center gap-1 text-blue-500 font-medium animate-pulse">
                            <RefreshCw className="w-3 h-3 animate-spin" />
                            Kaydediliyor...
                        </span>
                    ) : hasUnsavedChanges ? (
                        <span className="flex items-center gap-1 text-orange-500 font-medium">
                            <CloudOff className="w-3 h-3" />
                            Kaydedilmedi
                        </span>
                    ) : (
                         <span className="flex items-center gap-1 text-gray-400 dark:text-gray-500">
                             <Cloud className="w-3 h-3" />
                             {lastSaved ? `Son kayıt: ${lastSaved.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}` : 'Hazır'}
                         </span>
                    )}
                </div>
            </div>
        </div>

        <div className="flex-1 flex items-center gap-2 overflow-hidden justify-center sm:justify-start">
          {isEditingTitle ? (
            <div className="flex items-center gap-2 w-full max-w-md">
              <input
                type="text"
                value={tempTitle}
                onChange={(e) => setTempTitle(e.target.value)}
                className="flex-1 border border-blue-300 dark:border-blue-500 rounded px-2 py-1 text-lg font-bold focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                autoFocus
                onKeyDown={(e) => e.key === 'Enter' && saveTitle()}
              />
              <button onClick={saveTitle} className="p-1 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/30 rounded">
                <CheckCircle className="w-5 h-5" />
              </button>
              <button onClick={() => { setIsEditingTitle(false); setTempTitle(exam.title); }} className="p-1 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded">
                <XCircle className="w-5 h-5" />
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2 group cursor-pointer max-w-full" onClick={() => setIsEditingTitle(true)}>
              <h1 className="text-lg font-bold truncate text-gray-800 dark:text-white" title="Başlığı düzenlemek için tıklayın">
                {exam.title}
              </h1>
              <Edit2 className="w-4 h-4 text-gray-400 dark:text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0" />
            </div>
          )}
        </div>

        <div className="flex items-center gap-2">
            <button 
                onClick={() => setIsEditMode(!isEditMode)}
                className={`flex-shrink-0 flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition ${isEditMode ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300' : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`}
                title="Düzenleme Modu"
            >
                {isEditMode ? <Check className="w-4 h-4" /> : <Edit2 className="w-4 h-4" />}
                <span className="hidden sm:inline">{isEditMode ? 'Tamamla' : 'Düzenle'}</span>
            </button>

            {exam.isFinished && !isEditMode && (
            <button 
                onClick={onResetRequest}
                className="flex-shrink-0 flex items-center gap-2 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-3 py-1.5 rounded-lg text-sm font-medium hover:bg-blue-200 dark:hover:bg-blue-900/50 transition"
            >
                <RotateCcw className="w-4 h-4" />
                <span className="hidden sm:inline">Yeniden Çalış</span>
            </button>
            )}
        </div>
      </div>

      {isEditMode && (
          <div className="bg-orange-50 dark:bg-orange-900/20 px-4 py-2 text-xs sm:text-sm text-orange-800 dark:text-orange-200 text-center border-b border-orange-100 dark:border-orange-900/30">
              Düzenleme Modu: Soruları ve şıkları değiştirebilirsiniz. Doğru cevabı ayarlamak için şık harfine (A, B...) tıklayın.
          </div>
      )}

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full">
        {exam.questions.length === 0 && (
             <div className="text-center py-10 opacity-60">
                 <p className="text-xl text-gray-500 dark:text-gray-400">Bu sınavda henüz soru yok.</p>
                 {isEditMode && <p className="text-sm mt-2 text-blue-500">Aşağıdaki butonu kullanarak soru ekleyin.</p>}
             </div>
        )}

        {exam.questions.map((q, index) => (
          <div key={q.id} className="mb-8 border-b border-gray-100 dark:border-gray-800 pb-6 last:border-0 group/question">
            <div className="flex gap-3 mb-4">
              <span className="font-bold text-gray-900 dark:text-gray-100 text-lg pt-1">{index + 1}.</span>
              <div className="flex-1">
                  {isEditMode ? (
                      <textarea 
                        value={q.text}
                        onChange={(e) => handleQuestionTextChange(q.id, e.target.value)}
                        className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:outline-none min-h-[80px]"
                        placeholder="Soru metni..."
                      />
                  ) : (
                      <p className="text-gray-800 dark:text-gray-200 text-lg leading-relaxed whitespace-pre-wrap">{q.text}</p>
                  )}
              </div>
              {isEditMode && (
                  <button onClick={() => deleteQuestion(q.id)} className="self-start p-2 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded">
                      <Trash2 className="w-5 h-5" />
                  </button>
              )}
            </div>

            <div className="space-y-3 pl-2 sm:pl-8">
              {q.options.map((opt) => {
                const isSelected = q.userSelection === opt.label;
                const isCorrect = q.correctAnswerLabel === opt.label;

                // Styling Logic
                let containerClass = "w-full text-left p-3 rounded-xl border-2 transition-all duration-200 flex items-start gap-3 group relative ";
                let labelClass = "font-bold min-w-[24px] ";
                let textClass = "flex-1 ";

                if (isEditMode) {
                    containerClass += isCorrect ? "border-green-500 bg-green-50 dark:bg-green-900/10 " : "border-dashed border-gray-300 dark:border-gray-700 hover:border-blue-400 ";
                    labelClass += isCorrect ? "text-green-700 cursor-pointer hover:scale-110 transition-transform " : "text-gray-500 cursor-pointer hover:text-blue-500 ";
                    textClass += "text-gray-900 dark:text-gray-300";
                } else if (!exam.isFinished) {
                  // Active Exam State
                  if (isSelected) {
                    containerClass += "border-green-500 bg-green-50 dark:bg-green-900/20 shadow-sm";
                    labelClass += "text-green-700 dark:text-green-400";
                    textClass += "text-gray-900 dark:text-gray-100";
                  } else {
                    containerClass += "border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-500 hover:bg-gray-50 dark:hover:bg-gray-800";
                    labelClass += "text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200";
                    textClass += "text-gray-900 dark:text-gray-300";
                  }
                } else {
                  // Finished State
                  if (isCorrect) {
                    // Doğru cevap (Yeşil)
                    containerClass += "border-green-500 bg-green-100/40 dark:bg-green-900/40 shadow-sm"; 
                    textClass += "text-green-800 dark:text-green-400 font-bold";
                    labelClass += "text-green-800 dark:text-green-400 font-bold";
                  } else if (isSelected) {
                    // Yanlış işaretlenmiş (Kırmızı)
                    containerClass += "border-red-500 bg-red-50 dark:bg-red-900/20 shadow-sm";
                    textClass += "text-red-700 dark:text-red-400 font-bold";
                    labelClass += "text-red-700 dark:text-red-400 font-bold";
                  } else {
                    // Diğer şıklar (Siyah/Nötr)
                    containerClass += "border-gray-200 dark:border-gray-700 opacity-60";
                    textClass += "text-gray-900 dark:text-gray-400";
                    labelClass += "text-gray-900 dark:text-gray-400 font-medium";
                  }
                }

                return (
                    <div key={opt.label} className="relative">
                        <button
                            onClick={() => handleOptionSelect(q.id, opt.label)}
                            disabled={exam.isFinished || isEditMode}
                            className={containerClass}
                        >
                            <span 
                                className={labelClass} 
                                title={isEditMode ? "Doğru cevap olarak işaretle" : ""}
                                onClick={(e) => {
                                    if(isEditMode) {
                                        e.stopPropagation();
                                        toggleCorrectAnswer(q.id, opt.label);
                                    }
                                }}
                            >
                                {opt.label})
                            </span>

                            {isEditMode ? (
                                <input 
                                    type="text"
                                    value={opt.text}
                                    onChange={(e) => handleOptionTextChange(q.id, opt.label, e.target.value)}
                                    className="flex-1 bg-transparent border-b border-transparent focus:border-blue-500 focus:outline-none w-full"
                                    placeholder="Şık metni..."
                                    onClick={e => e.stopPropagation()}
                                />
                            ) : (
                                <span className={textClass}>{opt.text}</span>
                            )}

                            {/* Icons Logic */}
                            {!isEditMode && isSelected && !exam.isFinished && (
                                <CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-500" />
                            )}
                            {!isEditMode && exam.isFinished && isCorrect && (
                                <CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-600 dark:text-green-400" />
                            )}
                            {!isEditMode && exam.isFinished && isSelected && !isCorrect && (
                                <XCircle className="absolute right-3 top-3 w-5 h-5 text-red-500 dark:text-red-400" />
                            )}
                        </button>
                        {isEditMode && (
                            <button 
                                onClick={() => removeOption(q.id, opt.label)}
                                className="absolute right-[-30px] top-4 text-red-300 hover:text-red-500"
                            >
                                <MinusCircle className="w-5 h-5" />
                            </button>
                        )}
                    </div>
                );
              })}

              {isEditMode && (
                  <button onClick={() => addOption(q.id)} className="text-sm text-blue-500 hover:text-blue-700 flex items-center gap-1 mt-2">
                      <PlusCircle className="w-4 h-4" /> Şık Ekle
                  </button>
              )}
            </div>
          </div>
        ))}

        {isEditMode ? (
             <button 
                onClick={addQuestion}
                className="w-full py-4 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-xl text-gray-500 hover:border-blue-500 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-gray-800 transition flex flex-col items-center justify-center gap-2 mb-12"
             >
                 <PlusCircle className="w-8 h-8" />
                 <span className="font-bold">Yeni Soru Ekle</span>
             </button>
        ) : (
             !exam.isFinished && exam.questions.length > 0 && (
                <div className="mt-8 mb-12 flex justify-center">
                    <button
                    onClick={finishExam}
                    className="bg-blue-600 text-white text-lg font-bold py-4 px-12 rounded-full shadow-lg hover:bg-blue-700 hover:shadow-xl transform hover:-translate-y-1 transition-all active:scale-95 dark:shadow-blue-900/50"
                    >
                    SINAVI BİTİR
                    </button>
                </div>
            )
        )}

        {exam.isFinished && !isEditMode && (
          <div className="mt-8 mb-12 p-6 bg-gray-100 dark:bg-gray-800 rounded-xl text-center border border-gray-200 dark:border-gray-700">
            <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">Sınav Tamamlandı</h3>
            <p className="text-gray-600 dark:text-gray-400 mb-4">Cevaplarınızı kontrol edin. Doğru şıklar yeşil, yanlış işaretlediğiniz şıklar kırmızı ile belirtilmiştir.</p>
            <button 
              onClick={onResetRequest}
              className="bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 font-semibold py-2 px-6 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 transition"
            >
              Yeniden Çalış
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  // --- Auth State ---
  const [currentUser, setCurrentUser] = useState<string | null>(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('sinav_asistani_active_user');
    }
    return null;
  });

  const [isInitialized, setIsInitialized] = useState(false);

  // --- State ---
  const [folders, setFolders] = useState<Folder[]>([]);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null);
  const [activeExamId, setActiveExamId] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string | null>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);

  // Persistence Tracking
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const foldersRef = useRef<Folder[]>([]); // To track folders in interval without dependencies
  const isDirtyRef = useRef(false);

  // Folder Renaming State
  const [isEditingFolderName, setIsEditingFolderName] = useState(false);
  const [tempFolderName, setTempFolderName] = useState("");
  const [editingFolderId, setEditingFolderId] = useState<string | null>(null);
  const [editFolderTempName, setEditFolderTempName] = useState("");

  // Modals State
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [examToDeleteId, setExamToDeleteId] = useState<string | null>(null);

  // Upload Report State
  const [uploadResults, setUploadResults] = useState<UploadResult[]>([]);
  const [isUploadReportOpen, setIsUploadReportOpen] = useState(false);

  // --- Persistence & Theme ---

  useEffect(() => {
    const savedTheme = localStorage.getItem('sinav_asistani_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setDarkMode(true);
    }
  }, []);

  // LOAD DATA
  useEffect(() => {
    if (currentUser) {
      setIsInitialized(false);
      const storageKey = getStorageKey(currentUser);
      const uiKey = getUiKey(currentUser);

      const savedData = localStorage.getItem(storageKey);
      if (savedData) {
        try {
          const parsed = JSON.parse(savedData);
          setFolders(parsed || []);
          foldersRef.current = parsed || [];
        } catch (e) {
          console.error("Data load error", e);
          setFolders([]);
          foldersRef.current = [];
        }
      } else {
        setFolders([]);
        foldersRef.current = [];
      }

      const savedUi = localStorage.getItem(uiKey);
      if (savedUi) {
        try {
          const ui = JSON.parse(savedUi);
          if (ui.currentView) setCurrentView(ui.currentView);
          if (ui.activeFolderId) setActiveFolderId(ui.activeFolderId);
          if (ui.activeExamId) setActiveExamId(ui.activeExamId);
        } catch (e) {
          console.error("UI state load error", e);
        }
      }
      setIsInitialized(true);
    }
  }, [currentUser]);

  // UPDATE REF & DIRTY STATUS WHEN STATE CHANGES
  useEffect(() => {
    if (isInitialized) {
        foldersRef.current = folders;
        isDirtyRef.current = true;
    }
  }, [folders, isInitialized]);

  // SAVE UI STATE (Navigation) - Save immediately on change
  useEffect(() => {
      if(currentUser && isInitialized) {
          const uiKey = getUiKey(currentUser);
          localStorage.setItem(uiKey, JSON.stringify({ currentView, activeFolderId, activeExamId }));
      }
  }, [currentView, activeFolderId, activeExamId, currentUser, isInitialized]);

  // SAVE DATA ENGINE (Auto-save interval & BeforeUnload)

  const performSave = useCallback(() => {
      if(!currentUser) return;
      setIsSaving(true);
      const storageKey = getStorageKey(currentUser);
      localStorage.setItem(storageKey, JSON.stringify(foldersRef.current));

      // Update UI feedback
      setLastSaved(new Date());
      isDirtyRef.current = false;
      setTimeout(() => setIsSaving(false), 800);
  }, [currentUser]);

  // 1. Interval Auto-Save (Every 30 seconds)
  useEffect(() => {
      const timer = setInterval(() => {
          if(isDirtyRef.current && isInitialized && currentUser) {
              performSave();
          }
      }, 30000); // 30 seconds

      return () => clearInterval(timer);
  }, [currentUser, isInitialized, performSave]);

  // 2. Before Unload (Browser warning & emergency save)
  useEffect(() => {
      const handleBeforeUnload = (e: BeforeUnloadEvent) => {
          if (isDirtyRef.current) {
              // Attempt synchronous save if possible (localStorage is sync)
              if(currentUser) {
                  const key = getStorageKey(currentUser);
                  localStorage.setItem(key, JSON.stringify(foldersRef.current));
              }

              // Standard way to trigger browser prompt
              e.preventDefault();
              e.returnValue = '';
          }
      };
      window.addEventListener('beforeunload', handleBeforeUnload);
      return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [currentUser]);

  // 3. Navigation Guard (Internal Back Button)
  const handleInternalNavigation = () => {
      if (isDirtyRef.current) {
          performSave(); // Force save before leaving screen
      }
  };

  // Validation
  useEffect(() => {
    if (!isInitialized) return;
    if (activeFolderId) {
        const folder = folders.find(f => f.id === activeFolderId);
        if (!folder) {
            setActiveFolderId(null);
            setCurrentView('DASHBOARD');
            return;
        }
        if (activeExamId) {
            const exam = folder.exams.find(e => e.id === activeExamId);
            if (!exam) {
                setActiveExamId(null);
                setCurrentView('FOLDER_DETAIL');
            }
        }
    }
  }, [folders, activeFolderId, activeExamId, isInitialized]);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('sinav_asistani_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('sinav_asistani_theme', 'light');
    }
  }, [darkMode]);

  useEffect(() => {
    if (activeFolderId) {
      const folder = folders.find(f => f.id === activeFolderId);
      if (folder) setTempFolderName(folder.name);
    }
  }, [activeFolderId, folders]);

  // --- Actions ---

  const handleLogin = (username: string) => {
    const trimmedUser = username.trim();
    localStorage.setItem('sinav_asistani_active_user', trimmedUser);
    setCurrentUser(trimmedUser);
  };

  const handleLogout = () => {
    if(isDirtyRef.current) performSave(); // Save on logout
    localStorage.removeItem('sinav_asistani_active_user');
    setCurrentUser(null);
    setFolders([]);
    setActiveFolderId(null);
    setActiveExamId(null);
    setCurrentView('DASHBOARD');
    setIsInitialized(false);
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  const createFolder = () => {
    const newId = crypto.randomUUID();
    const defaultName = "Yeni Klasör";
    const newFolder: Folder = { id: newId, name: defaultName, exams: [] };
    setFolders(prev => [...prev, newFolder]);
    setEditingFolderId(newId);
    setEditFolderTempName(defaultName);
  };

  const deleteFolder = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Bu klasörü ve içindeki tüm sınavları silmek istediğinize emin misiniz?")) {
      setFolders(folders.filter(f => f.id !== id));
      if (activeFolderId === id) {
        setActiveFolderId(null);
        setCurrentView('DASHBOARD');
      }
    }
  };

  const startEditingFolder = (e: React.MouseEvent, folder: Folder) => {
    e.stopPropagation();
    setEditingFolderId(folder.id);
    setEditFolderTempName(folder.name);
  };

  const saveFolderEdit = (e: React.MouseEvent | React.FormEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    if (editingFolderId && editFolderTempName.trim()) {
      setFolders(prev => prev.map(f => f.id === editingFolderId ? { ...f, name: editFolderTempName } : f));
      setEditingFolderId(null);
    } else {
      setEditingFolderId(null);
    }
  };

  const cancelFolderEdit = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.stopPropagation();
    setEditingFolderId(null);
  };

  const saveFolderNameDetail = () => {
    if (activeFolderId && tempFolderName.trim()) {
      setFolders(prev => prev.map(f => f.id === activeFolderId ? { ...f, name: tempFolderName } : f));
      setIsEditingFolderName(false);
    } else {
      const folder = folders.find(f => f.id === activeFolderId);
      if (folder) setTempFolderName(folder.name);
      setIsEditingFolderName(false);
    }
  };

  // --- File Upload Logic ---

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>, targetFolderId?: string) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    let folderId = targetFolderId || activeFolderId;
    let newFolderId = "";

    // Implicit folder creation
    if (!folderId) {
      newFolderId = crypto.randomUUID();
      folderId = newFolderId;
      const newFolder: Folder = { id: newFolderId, name: "Genel", exams: [] };
      setFolders(prev => [...prev, newFolder]);
    }

    setCurrentView('LOADING');
    setUploadResults([]); // Clear previous results

    const results: UploadResult[] = [];
    const processedExams: { folderId: string, exam: Exam }[] = [];

    // Process all files
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setLoadingMessage(`Dosya işleniyor (${i + 1}/${files.length}): ${file.name}`);

      try {
        const mimeType = getMimeType(file);
        let data = '';
        if (mimeType.startsWith('text/')) {
          data = await fileToText(file);
        } else {
          data = await fileToBase64(file);
        }

        const parsedData = await parseExamFile(data, mimeType);

        // Check if parsing yielded no questions - treat as error/warning
        if (parsedData.questions.length === 0) {
            results.push({ fileName: file.name, status: 'error', message: "Soru bulunamadı veya dosya okunamadı." });
        } else {
            const newExam: Exam = {
                id: crypto.randomUUID(),
                title: parsedData.title,
                dateCreated: new Date().toISOString(),
                questions: parsedData.questions,
                isFinished: false
            };
            processedExams.push({ folderId: folderId!, exam: newExam });
            results.push({ fileName: file.name, status: 'success' });
        }

      } catch (error) {
        console.error(`Error processing file ${file.name}:`, error);
        results.push({ fileName: file.name, status: 'error', message: "İşlem hatası" });
      }
    }

    // Batch update state
    if (processedExams.length > 0) {
        setFolders(prev => prev.map(f => {
            const folderExamsToAdd = processedExams.filter(pe => pe.folderId === f.id).map(pe => pe.exam);
            if (folderExamsToAdd.length > 0) {
                return { ...f, exams: [...f.exams, ...folderExamsToAdd] };
            }
            return f;
        }));
    }

    setUploadResults(results);
    setLoadingMessage(null);

    // Navigation logic
    const hasErrors = results.some(r => r.status === 'error');

    // If there are errors, or mix of success/errors, show report
    if (hasErrors) {
        if (!activeFolderId && newFolderId) setActiveFolderId(newFolderId);
        setCurrentView('FOLDER_DETAIL'); // Go to folder view behind modal
        setIsUploadReportOpen(true);
    } else {
        // All success
        if (!activeFolderId && newFolderId) setActiveFolderId(newFolderId);

        // If single file, go to it
        if (files.length === 1 && processedExams.length === 1) {
            setActiveExamId(processedExams[0].exam.id);
            setCurrentView('EXAM_TAKER');
        } else {
            setCurrentView('FOLDER_DETAIL');
        }
    }
  };

  const handleManualCreate = (fileName: string) => {
      // Create empty exam
      if (!activeFolderId) return;

      const newExam: Exam = {
          id: crypto.randomUUID(),
          title: fileName,
          dateCreated: new Date().toISOString(),
          questions: [],
          isFinished: false
      };

      setFolders(prev => prev.map(f => {
          if (f.id === activeFolderId) {
              return { ...f, exams: [...f.exams, newExam] };
          }
          return f;
      }));

      setIsUploadReportOpen(false);
      setActiveExamId(newExam.id);
      setCurrentView('EXAM_TAKER');
      // The ExamTaker component will show empty state or auto-enable edit mode conceptually
  };

  const updateExamInState = (updatedExam: Exam) => {
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        return {
          ...f,
          exams: f.exams.map(e => e.id === updatedExam.id ? updatedExam : e)
        };
      }
      return f;
    }));
  };

  // --- Reset & Archive Logic ---

  const handleResetRequest = () => setIsResetModalOpen(true);

  const handleArchiveAndReset = () => {
    if (!activeFolderId || !activeExamId) return;
    setFolders(prev => prev.map(f => {
      if (f.id === activeFolderId) {
        const currentExam = f.exams.find(e => e.id === activeExamId);
        if (!currentExam) return f;
        const dateStr = new Date().toLocaleDateString('tr-TR', { hour: '2-digit', minute: '2-digit' });
        const archivedExam: Exam = {
          ...JSON.parse(JSON.stringify(currentExam)),
          id: crypto.randomUUID(),
          title: `${currentExam.title} (Tamamlandı - ${dateStr})`,
          isFinished: true,
        };
        const resetExam: Exam = {
          ...currentExam,
          isFinished: false,
          questions: currentExam.questions.map(q => ({ ...q, userSelection: null }))
        };
        return { ...f, exams: [...f.exams.filter(e => e.id !== activeExamId), archivedExam, resetExam] };
      }
      return f;
    }));
    setIsResetModalOpen(false);
  };

  const handleJustReset = () => {
    if (!activeFolderId || !activeExamId) return;
    setFolders(prev => prev.map(f => {
