                onBack={() => { handleInternalNavigation(); setCurrentView('FOLDER_DETAIL'); }} 
                onResetRequest={handleResetRequest}
                isSaving={isSaving}
                lastSaved={lastSaved}
                hasUnsavedChanges={isDirtyRef.current}
              />
            </div>
          );
        })()}
      </div>
    </div>
  );
};

