import { createClient, SupabaseClient, User } from '@supabase/supabase-js';
import { Folder } from '../types';

export interface SupabaseConfig {
  url: string;
  anonKey: string;
}

let supabase: SupabaseClient | undefined;

// Initialize Supabase
export const initSupabase = (config: SupabaseConfig) => {
  if (!config.url || !config.anonKey) throw new Error("Supabase URL ve Key gerekli.");

  try {
    // Always create a new client to ensure configuration updates are applied immediately.
    // The previous singleton check (if !supabase) prevented correcting invalid keys.
    supabase = createClient(config.url, config.anonKey, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: false
      }
    });
  } catch(e) {
      console.error("Supabase init error", e);
      throw e;
  }
  return supabase;
};

export const getSupabase = () => supabase;
export const isSupabaseInitialized = () => !!supabase;

// Helper to convert username to fake email (Supabase requires email)
// Using a consistent transformation
const getEmail = (username: string) => `${username.trim().toLowerCase()}@sinavasistani.app`;

export const cloudLogin = async (username: string, password: string): Promise<User> => {
  if (!supabase) throw new Error("Bulut servisi başlatılmadı. Lütfen ayarlardan bağlantıyı kurun.");

  const { data, error } = await supabase.auth.signInWithPassword({
    email: getEmail(username),
    password: password,
  });

  if (error) {
    console.error("Supabase Login Error:", error);
    if (error.message.includes("Invalid login") || error.message.includes("invalid_grant")) {
        throw new Error("Kullanıcı adı veya şifre hatalı. (Eğer yeni kayıt olduysanız, Supabase panelinden 'Confirm Email' seçeneğini kapattığınızdan emin olun.)");
    }
    if (error.message.includes("Email not confirmed")) {
        throw new Error("E-posta onayı gerekli. Lütfen Supabase panelinden e-posta onayını kapatınız ve tekrar kayıt olmayı deneyiniz.");
    }
    throw new Error(`Giriş hatası: ${error.message}`);
  }

  if (!data.user) throw new Error("Kullanıcı verisi alınamadı.");
  return data.user;
};

export const cloudRegister = async (username: string, password: string): Promise<User> => {
  if (!supabase) throw new Error("Bulut servisi başlatılmadı.");

  const { data, error } = await supabase.auth.signUp({
    email: getEmail(username),
    password: password,
  });

  if (error) {
    console.error("Supabase Register Error:", error);
    if (error.message.includes("already registered") || error.code === 'user_already_exists') {
        throw new Error("Bu kullanıcı adı zaten alınmış.");
    }
    throw new Error(`Kayıt hatası: ${error.message}`);
  }

  if (!data.user) throw new Error("Kayıt oluşturulamadı.");

  // Check if session is established (implies email confirm is disabled or not required)
  if (!data.session) {
      // If no session, it usually means email confirmation is required/pending
      throw new Error("Kayıt başarılı ancak otomatik giriş yapılamadı. Lütfen Supabase panelinde 'Confirm Email' ayarının kapalı olduğundan emin olun ve giriş yapmayı deneyin.");
  }

  return data.user;
};

export const cloudLogout = async () => {
  if (!supabase) return;
  await supabase.auth.signOut();
};

export const saveUserData = async (userId: string, folders: Folder[]) => {
  if (!supabase) return;

  // Upsert into 'profiles' table. 
  // Requires table: create table profiles (id uuid primary key, content jsonb);
  const { error } = await supabase
    .from('profiles')
    .upsert({ 
        id: userId, 
        content: JSON.stringify(folders),
        updated_at: new Date().toISOString()
    });

  if (error) {
      console.error("Supabase save error:", error);
      throw new Error("Veri kaydedilemedi. Lütfen 'profiles' tablosunun oluşturulduğundan emin olun.");
  }
};

export const loadUserData = async (userId: string): Promise<Folder[] | null> => {
  if (!supabase) return null;

  const { data, error } = await supabase
    .from('profiles')
    .select('content')
    .eq('id', userId)
    .single();

  if (error) {
      // PGRST116 means no rows returned (user has no data yet), which is fine.
      if (error.code !== 'PGRST116') {
          console.error("Supabase load error", error);
      }
      return [];
  }

  if (data && data.content) {
    try {
      return JSON.parse(data.content);
    } catch (e) {
      console.error("Cloud data parse error", e);
      return [];
    }
  }
  return [];
};

