// ... ExamTaker ...
interface ExamTakerProps {
  exam: Exam;
  onUpdateExam: (updatedExam: Exam) => void;
  onBack: () => void;
  onResetRequest: () => void;
  onFinishRequest: () => void; // New Prop
  isSaving: boolean;
  lastSaved: Date | null;
  hasUnsavedChanges: boolean;
  scrollToBottom: () => void; // New Prop
}

const ExamTaker: React.FC<ExamTakerProps> = ({ exam, onUpdateExam, onBack, onResetRequest, onFinishRequest, isSaving, lastSaved, hasUnsavedChanges, scrollToBottom }) => {
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [tempTitle, setTempTitle] = useState(exam.title);
  const [isEditMode, setIsEditMode] = useState(false);

  useEffect(() => { setTempTitle(exam.title); }, [exam.title]);

  // If exam becomes finished, scroll to bottom
  useEffect(() => {
      if (exam.isFinished) {
          setTimeout(scrollToBottom, 200);
      }
  }, [exam.isFinished, scrollToBottom]);

  const handleOptionSelect = (questionId: number, label: string) => {
    if (isEditMode) return; 
    if (exam.isFinished) return;
    const updatedQuestions = exam.questions.map(q => {
      if (q.id === questionId) { return { ...q, userSelection: q.userSelection === label ? null : label }; }
      return q;
    });
    onUpdateExam({ ...exam, questions: updatedQuestions });
  };

  const saveTitle = () => {
    if (tempTitle.trim()) { onUpdateExam({ ...exam, title: tempTitle }); } else { setTempTitle(exam.title); }
    setIsEditingTitle(false);
  };

  const handleQuestionTextChange = (qId: number, text: string) => { const updated = exam.questions.map(q => q.id === qId ? { ...q, text } : q); onUpdateExam({ ...exam, questions: updated }); };
  const handleOptionTextChange = (qId: number, optLabel: string, text: string) => { const updated = exam.questions.map(q => { if (q.id === qId) { return { ...q, options: q.options.map(o => o.label === optLabel ? { ...o, text } : o) }; } return q; }); onUpdateExam({ ...exam, questions: updated }); };
  const toggleCorrectAnswer = (qId: number, label: string) => { const updated = exam.questions.map(q => { if (q.id === qId) { return { ...q, correctAnswerLabel: q.correctAnswerLabel === label ? null : label }; } return q; }); onUpdateExam({ ...exam, questions: updated }); };
  const addOption = (qId: number) => { const updated = exam.questions.map(q => { if (q.id === qId) { const labels = ["A", "B", "C", "D", "E", "F", "G"]; const nextLabel = labels[q.options.length] || "X"; return { ...q, options: [...q.options, { label: nextLabel, text: "" }] }; } return q; }); onUpdateExam({ ...exam, questions: updated }); };
  const removeOption = (qId: number, label: string) => { const updated = exam.questions.map(q => { if (q.id === qId) { const filtered = q.options.filter(o => o.label !== label); const remapped = filtered.map((o, idx) => { const labels = ["A", "B", "C", "D", "E", "F", "G"]; return { ...o, label: labels[idx] || "?" }; }); return { ...q, options: remapped, correctAnswerLabel: null }; } return q; }); onUpdateExam({ ...exam, questions: updated }); };
  const deleteQuestion = (qId: number) => { if(!confirm("Soruyu silmek istediğinize emin misiniz?")) return; const updated = exam.questions.filter(q => q.id !== qId); onUpdateExam({ ...exam, questions: updated }); };
  const addQuestion = () => { const newQ: Question = { id: Math.floor(Math.random() * 100000), text: "", options: [ { label: "A", text: "" }, { label: "B", text: "" }, { label: "C", text: "" }, { label: "D", text: "" }, ], correctAnswerLabel: null, userSelection: null }; onUpdateExam({ ...exam, questions: [...exam.questions, newQ] }); setTimeout(scrollToBottom, 100); };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-gray-900 transition-colors">
      <div className="sticky top-0 z-30 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 shadow-sm px-4 py-3 flex items-center justify-between gap-4 transition-colors">
        <div className="flex items-center gap-2">
            <button onClick={onBack} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition flex-shrink-0"><ArrowLeft className="w-6 h-6 text-gray-600 dark:text-gray-300" /></button>
            <div className="hidden sm:flex flex-col"><div className="flex items-center gap-1.5 text-xs">{isSaving ? (<span className="flex items-center gap-1 text-blue-500 font-medium animate-pulse"><RefreshCw className="w-3 h-3 animate-spin" /> Kaydediliyor...</span>) : hasUnsavedChanges ? (<span className="flex items-center gap-1 text-orange-500 font-medium"><CloudOff className="w-3 h-3" /> Kaydedilmedi</span>) : (<span className="flex items-center gap-1 text-gray-400 dark:text-gray-500"><Cloud className="w-3 h-3" /> {lastSaved ? `Son kayıt: ${lastSaved.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}` : 'Hazır'}</span>)}</div></div>
        </div>
        <div className="flex-1 flex items-center gap-2 overflow-hidden justify-center sm:justify-start">{isEditingTitle ? (<div className="flex items-center gap-2 w-full max-w-md"><input type="text" value={tempTitle} onChange={(e) => setTempTitle(e.target.value)} className="flex-1 border border-blue-300 dark:border-blue-500 rounded px-2 py-1 text-lg font-bold focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-800 text-gray-900 dark:text-white" autoFocus onKeyDown={(e) => e.key === 'Enter' && saveTitle()} /><button onClick={saveTitle} className="p-1 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/30 rounded"><CheckCircle className="w-5 h-5" /></button><button onClick={() => { setIsEditingTitle(false); setTempTitle(exam.title); }} className="p-1 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded"><XCircle className="w-5 h-5" /></button></div>) : (<div className="flex items-center gap-2 group cursor-pointer max-w-full" onClick={() => setIsEditingTitle(true)}><h1 className="text-lg font-bold truncate text-gray-800 dark:text-white" title="Başlığı düzenlemek için tıklayın">{exam.title}</h1><Edit2 className="w-4 h-4 text-gray-400 dark:text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0" /></div>)}</div>
        <div className="flex items-center gap-2"><button onClick={() => setIsEditMode(!isEditMode)} className={`flex-shrink-0 flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition ${isEditMode ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300' : 'bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`} title="Düzenleme Modu">{isEditMode ? <Check className="w-4 h-4" /> : <Edit2 className="w-4 h-4" />}<span className="hidden sm:inline">{isEditMode ? 'Tamamla' : 'Düzenle'}</span></button>{exam.isFinished && !isEditMode && (<button onClick={onResetRequest} className="flex-shrink-0 flex items-center gap-2 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-3 py-1.5 rounded-lg text-sm font-medium hover:bg-blue-200 dark:hover:bg-blue-900/50 transition"><RotateCcw className="w-4 h-4" /><span className="hidden sm:inline">Yeniden Çalış</span></button>)}</div>
      </div>
      {isEditMode && (<div className="bg-orange-50 dark:bg-orange-900/20 px-4 py-2 text-xs sm:text-sm text-orange-800 dark:text-orange-200 text-center border-b border-orange-100 dark:border-orange-900/30">Düzenleme Modu: Soruları ve şıkları değiştirebilirsiniz. Doğru cevabı ayarlamak için şık harfine (A, B...) tıklayın.</div>)}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 max-w-3xl mx-auto w-full">
        {exam.questions.length === 0 && (<div className="text-center py-10 opacity-60"><p className="text-xl text-gray-500 dark:text-gray-400">Bu sınavda henüz soru yok.</p>{isEditMode && <p className="text-sm mt-2 text-blue-500">Aşağıdaki butonu kullanarak soru ekleyin.</p>}</div>)}
        {exam.questions.map((q, index) => (
          <div key={q.id} className="mb-8 border-b border-gray-100 dark:border-gray-800 pb-6 last:border-0 group/question">
            <div className="flex gap-3 mb-4"><span className="font-bold text-gray-900 dark:text-gray-100 text-lg pt-1">{index + 1}.</span><div className="flex-1">{isEditMode ? (<textarea value={q.text} onChange={(e) => handleQuestionTextChange(q.id, e.target.value)} className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:outline-none min-h-[80px]" placeholder="Soru metni..." />) : (<p className="text-gray-800 dark:text-gray-200 text-lg leading-relaxed whitespace-pre-wrap">{q.text}</p>)}</div>{isEditMode && (<button onClick={() => deleteQuestion(q.id)} className="self-start p-2 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded"><Trash2 className="w-5 h-5" /></button>)}</div>
            <div className="space-y-3 pl-2 sm:pl-8">
              {q.options.map((opt) => {
                const isSelected = q.userSelection === opt.label; const isCorrect = q.correctAnswerLabel === opt.label;
                let containerClass = "w-full text-left p-3 rounded-xl border-2 transition-all duration-200 flex items-start gap-3 group relative ";
                let labelClass = "font-bold min-w-[24px] "; let textClass = "flex-1 ";
                if (isEditMode) { containerClass += isCorrect ? "border-green-500 bg-green-50 dark:bg-green-900/10 " : "border-dashed border-gray-300 dark:border-gray-700 hover:border-blue-400 "; labelClass += isCorrect ? "text-green-700 cursor-pointer hover:scale-110 transition-transform " : "text-gray-500 cursor-pointer hover:text-blue-500 "; textClass += "text-gray-900 dark:text-gray-300"; } 
                else if (!exam.isFinished) { if (isSelected) { containerClass += "border-green-500 bg-green-50 dark:bg-green-900/20 shadow-sm"; labelClass += "text-green-700 dark:text-green-400"; textClass += "text-gray-900 dark:text-gray-100"; } else { containerClass += "border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-500 hover:bg-gray-50 dark:hover:bg-gray-800"; labelClass += "text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200"; textClass += "text-gray-900 dark:text-gray-300"; } } 
                else { if (isCorrect) { containerClass += "border-green-500 bg-green-100/40 dark:bg-green-900/40 shadow-sm"; textClass += "text-green-800 dark:text-green-400 font-bold"; labelClass += "text-green-800 dark:text-green-400 font-bold"; } else if (isSelected) { containerClass += "border-red-500 bg-red-50 dark:bg-red-900/20 shadow-sm"; textClass += "text-red-700 dark:text-red-400 font-bold"; labelClass += "text-red-700 dark:text-red-400 font-bold"; } else { containerClass += "border-gray-200 dark:border-gray-700 opacity-60"; textClass += "text-gray-900 dark:text-gray-400"; labelClass += "text-gray-900 dark:text-gray-400 font-medium"; } }
                return (<div key={opt.label} className="relative"><button onClick={() => handleOptionSelect(q.id, opt.label)} disabled={exam.isFinished || isEditMode} className={containerClass}><span className={labelClass} title={isEditMode ? "Doğru cevap olarak işaretle" : ""} onClick={(e) => { if(isEditMode) { e.stopPropagation(); toggleCorrectAnswer(q.id, opt.label); } }}>{opt.label})</span>{isEditMode ? (<input type="text" value={opt.text} onChange={(e) => handleOptionTextChange(q.id, opt.label, e.target.value)} className="flex-1 bg-transparent border-b border-transparent focus:border-blue-500 focus:outline-none w-full" placeholder="Şık metni..." onClick={e => e.stopPropagation()} />) : (<span className={textClass}>{opt.text}</span>)}{!isEditMode && isSelected && !exam.isFinished && (<CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-500" />)}{!isEditMode && exam.isFinished && isCorrect && (<CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-600 dark:text-green-400" />)}{!isEditMode && exam.isFinished && isSelected && !isCorrect && (<XCircle className="absolute right-3 top-3 w-5 h-5 text-red-500 dark:text-red-400" />)}</button>{isEditMode && (<button onClick={() => removeOption(q.id, opt.label)} className="absolute right-[-30px] top-4 text-red-300 hover:text-red-500"><MinusCircle className="w-5 h-5" /></button>)}</div>);
              })}
              {isEditMode && (<button onClick={() => addOption(q.id)} className="text-sm text-blue-500 hover:text-blue-700 flex items-center gap-1 mt-2"><PlusCircle className="w-4 h-4" /> Şık Ekle</button>)}
            </div>
          </div>
        ))}
        {isEditMode ? (<button onClick={addQuestion} className="w-full py-4 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-xl text-gray-500 hover:border-blue-500 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-gray-800 transition flex flex-col items-center justify-center gap-2 mb-12"><PlusCircle className="w-8 h-8" /><span className="font-bold">Yeni Soru Ekle</span></button>) : (!exam.isFinished && exam.questions.length > 0 && (<div className="mt-8 mb-12 flex justify-center"><button onClick={onFinishRequest} className="bg-blue-600 text-white text-lg font-bold py-4 px-12 rounded-full shadow-lg hover:bg-blue-700 hover:shadow-xl transform hover:-translate-y-1 transition-all active:scale-95 dark:shadow-blue-900/50">SINAVI BİTİR</button></div>))}
        {exam.isFinished && !isEditMode && (<div className="mt-8 mb-12 p-6 bg-gray-100 dark:bg-gray-800 rounded-xl text-center border border-gray-200 dark:border-gray-700"><h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">Sınav Tamamlandı</h3><p className="text-gray-600 dark:text-gray-400 mb-4">Cevaplarınızı kontrol edin. Doğru şıklar yeşil, yanlış işaretlediğiniz şıklar kırmızı ile belirtilmiştir.</p><button onClick={onResetRequest} className="bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 font-semibold py-2 px-6 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 transition">Yeniden Çalış</button></div>)}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
  // ... state logic ...
  const [currentUser, setCurrentUser] = useState<string | null>(() => { if (typeof window !== 'undefined') return localStorage.getItem('sinav_asistani_active_user'); return null; });
  const [isCloudSession, setIsCloudSession] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [folders, setFolders] = useState<Folder[]>([]);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [activeFolderId, setActiveFolderId] = useState<string | null>(null);
  const [activeExamId, setActiveExamId] = useState<string | null>(null);
  const [loadingMessage, setLoadingMessage] = useState<string | null>(null);
  const [darkMode, setDarkMode] = useState<boolean>(false);
  const [defaultFolderId, setDefaultFolderId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const foldersRef = useRef<Folder[]>([]); 
  const isDirtyRef = useRef(false);
  const [isServerModalOpen, setIsServerModalOpen] = useState(false);
  const [supabaseConfig, setSupabaseConfig] = useState<SupabaseConfig>(() => { const stored = localStorage.getItem(SUPABASE_CONFIG_KEY); if (stored) return JSON.parse(stored); const defaults = getDefaultConfig(); if (defaults.url && defaults.anonKey) return defaults; return { url: '', anonKey: '' }; });
  const [isEditingFolderName, setIsEditingFolderName] = useState(false);
  const [tempFolderName, setTempFolderName] = useState("");
  const [editingFolderId, setEditingFolderId] = useState<string | null>(null);
  const [editFolderTempName, setEditFolderTempName] = useState("");

  // Modals State
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [isFinishModalOpen, setIsFinishModalOpen] = useState(false); // New
  const [examToDeleteId, setExamToDeleteId] = useState<string | null>(null);
  const [uploadResults, setUploadResults] = useState<UploadResult[]>([]);
  const [isUploadReportOpen, setIsUploadReportOpen] = useState(false);

  // Scroll Ref
  const mainScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => { if (supabaseConfig.url) { try { initSupabase(supabaseConfig); } catch(e) { console.error("Supabase init failed", e); } } }, [supabaseConfig]);
  useEffect(() => { const savedTheme = localStorage.getItem('sinav_asistani_theme'); if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) { setDarkMode(true); } }, []);
  useEffect(() => { if (currentUser) { setIsInitialized(false); const load = async () => { let loadedFolders: Folder[] = []; if (isCloudSession) { try { const { data } = await initSupabase(supabaseConfig).auth.getSession(); if (data && data.session?.user) { const userData = await loadUserData(data.session.user.id); if (userData) loadedFolders = userData; } } catch(e) { console.error("Cloud load error", e); alert("Bulut verisi çekilemedi."); } } else { const storageKey = getStorageKey(currentUser); const savedData = localStorage.getItem(storageKey); if (savedData) { try { loadedFolders = JSON.parse(savedData); } catch (e) { console.error("Data load error", e); } } } setFolders(loadedFolders); foldersRef.current = loadedFolders; setIsInitialized(true); const uiKey = getUiKey(currentUser); const savedUi = localStorage.getItem(uiKey); if (savedUi) { try { const ui = JSON.parse(savedUi); if (ui.currentView) setCurrentView(ui.currentView); if (ui.activeFolderId) setActiveFolderId(ui.activeFolderId); if (ui.activeExamId) setActiveExamId(ui.activeExamId); } catch (e) { console.error("UI state load error", e); } } const settingsKey = getSettingsKey(currentUser); const savedSettings = localStorage.getItem(settingsKey); if (savedSettings) { try { const parsedSettings = JSON.parse(savedSettings); if (parsedSettings.defaultFolderId) setDefaultFolderId(parsedSettings.defaultFolderId); } catch(e) { console.error("Settings load error", e); } } }; load(); } }, [currentUser, isCloudSession, supabaseConfig]);
  useEffect(() => { if (isInitialized) { foldersRef.current = folders; isDirtyRef.current = true; } }, [folders, isInitialized]);
  useEffect(() => { if(currentUser && isInitialized) { const uiKey = getUiKey(currentUser); localStorage.setItem(uiKey, JSON.stringify({ currentView, activeFolderId, activeExamId })); } }, [currentView, activeFolderId, activeExamId, currentUser, isInitialized]);
  useEffect(() => { if (currentUser && isInitialized) { const settingsKey = getSettingsKey(currentUser); localStorage.setItem(settingsKey, JSON.stringify({ defaultFolderId })); } }, [defaultFolderId, currentUser, isInitialized]);
  const performSave = useCallback(async () => { if(!currentUser) return; setIsSaving(true); try { if (isCloudSession && isSupabaseInitialized()) { const { data } = await initSupabase(supabaseConfig).auth.getSession(); if (data && data.session?.user) { await saveUserData(data.session.user.id, foldersRef.current); } } else { const storageKey = getStorageKey(currentUser); localStorage.setItem(storageKey, JSON.stringify(foldersRef.current)); } setLastSaved(new Date()); isDirtyRef.current = false; } catch (e) { console.error("Save failed", e); } finally { setTimeout(() => setIsSaving(false), 800); } }, [currentUser, isCloudSession, supabaseConfig]);
  useEffect(() => { const timer = setInterval(() => { if(isDirtyRef.current && isInitialized && currentUser) { performSave(); } }, 30000); return () => clearInterval(timer); }, [currentUser, isInitialized, performSave]);
  useEffect(() => { const handleBeforeUnload = (e: BeforeUnloadEvent) => { if (isDirtyRef.current) { if (!isCloudSession && currentUser) { const key = getStorageKey(currentUser); localStorage.setItem(key, JSON.stringify(foldersRef.current)); } e.preventDefault(); e.returnValue = ''; } }; window.addEventListener('beforeunload', handleBeforeUnload); return () => window.removeEventListener('beforeunload', handleBeforeUnload); }, [currentUser, isCloudSession]);
  const handleInternalNavigation = () => { if (isDirtyRef.current) performSave(); };
  useEffect(() => { if (!isInitialized) return; if (activeFolderId) { const folder = folders.find(f => f.id === activeFolderId); if (!folder) { setActiveFolderId(null); setCurrentView('DASHBOARD'); return; } if (activeExamId) { const exam = folder.exams.find(e => e.id === activeExamId); if (!exam) { setActiveExamId(null); setCurrentView('FOLDER_DETAIL'); } } } }, [folders, activeFolderId, activeExamId, isInitialized]);
  useEffect(() => { if (darkMode) { document.documentElement.classList.add('dark'); localStorage.setItem('sinav_asistani_theme', 'dark'); } else { document.documentElement.classList.remove('dark'); localStorage.setItem('sinav_asistani_theme', 'light'); } }, [darkMode]);
  useEffect(() => { if (activeFolderId) { const folder = folders.find(f => f.id === activeFolderId); if (folder) setTempFolderName(folder.name); } }, [activeFolderId, folders]);

  const handleLogin = (username: string, cloudMode: boolean) => { const trimmedUser = username.trim(); localStorage.setItem('sinav_asistani_active_user', trimmedUser); setCurrentUser(trimmedUser); setIsCloudSession(cloudMode); };
  const handleLogout = async () => { if(isDirtyRef.current) await performSave(); if (isCloudSession) await cloudLogout(); localStorage.removeItem('sinav_asistani_active_user'); setCurrentUser(null); setFolders([]); setActiveFolderId(null); setActiveExamId(null); setDefaultFolderId(null); setCurrentView('DASHBOARD'); setIsInitialized(false); setIsCloudSession(false); };
  const handleServerConfigSave = (config: SupabaseConfig) => { setSupabaseConfig(config); localStorage.setItem(SUPABASE_CONFIG_KEY, JSON.stringify(config)); setIsServerModalOpen(false); };
  const toggleDarkMode = () => setDarkMode(!darkMode);
  const createFolder = () => { const newId = crypto.randomUUID(); const defaultName = "Yeni Klasör"; const newFolder: Folder = { id: newId, name: defaultName, exams: [] }; setFolders(prev => [...prev, newFolder]); setEditingFolderId(newId); setEditFolderTempName(defaultName); };
  const deleteFolder = (e: React.MouseEvent, id: string) => { e.stopPropagation(); if (confirm("Bu klasörü ve içindeki tüm sınavları silmek istediğinize emin misiniz?")) { setFolders(folders.filter(f => f.id !== id)); if (activeFolderId === id) { setActiveFolderId(null); setCurrentView('DASHBOARD'); } if (defaultFolderId === id) setDefaultFolderId(null); } };
  const startEditingFolder = (e: React.MouseEvent, folder: Folder) => { e.stopPropagation(); setEditingFolderId(folder.id); setEditFolderTempName(folder.name); };
  const saveFolderEdit = (e: React.MouseEvent | React.FormEvent | React.KeyboardEvent) => { e.stopPropagation(); if (editingFolderId && editFolderTempName.trim()) { setFolders(prev => prev.map(f => f.id === editingFolderId ? { ...f, name: editFolderTempName } : f)); setEditingFolderId(null); } else { setEditingFolderId(null); } };
  const cancelFolderEdit = (e: React.MouseEvent | React.KeyboardEvent) => { e.stopPropagation(); setEditingFolderId(null); };
  const saveFolderNameDetail = () => { if (activeFolderId && tempFolderName.trim()) { setFolders(prev => prev.map(f => f.id === activeFolderId ? { ...f, name: tempFolderName } : f)); setIsEditingFolderName(false); } else { const folder = folders.find(f => f.id === activeFolderId); if (folder) setTempFolderName(folder.name); setIsEditingFolderName(false); } };
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>, targetFolderId?: string) => { const files = event.target.files; if (!files || files.length === 0) return; let folderId = targetFolderId || activeFolderId; if (!folderId && defaultFolderId) { const exists = folders.find(f => f.id === defaultFolderId); if (exists) { folderId = defaultFolderId; } else { setDefaultFolderId(null); } } let newFolderId = ""; if (!folderId) { newFolderId = crypto.randomUUID(); folderId = newFolderId; const newFolder: Folder = { id: newFolderId, name: "Genel", exams: [] }; setFolders(prev => [...prev, newFolder]); } setCurrentView('LOADING'); setUploadResults([]); const results: UploadResult[] = []; const processedExams: { folderId: string, exam: Exam }[] = []; for (let i = 0; i < files.length; i++) { const file = files[i]; setLoadingMessage(`Dosya işleniyor (${i + 1}/${files.length}): ${file.name}`); try { const mimeType = getMimeType(file); let data = ''; if (mimeType.startsWith('text/')) { data = await fileToText(file); } else { data = await fileToBase64(file); } const parsedData = await parseExamFile(data, mimeType); if (parsedData.questions.length === 0) { results.push({ fileName: file.name, status: 'error', message: "Soru bulunamadı veya dosya okunamadı." }); } else { const newExam: Exam = { id: crypto.randomUUID(), title: parsedData.title, dateCreated: new Date().toISOString(), questions: parsedData.questions, isFinished: false }; processedExams.push({ folderId: folderId!, exam: newExam }); results.push({ fileName: file.name, status: 'success' }); } } catch (error) { console.error(`Error processing file ${file.name}:`, error); results.push({ fileName: file.name, status: 'error', message: "İşlem hatası" }); } } if (processedExams.length > 0) { setFolders(prev => prev.map(f => { const folderExamsToAdd = processedExams.filter(pe => pe.folderId === f.id).map(pe => pe.exam); if (folderExamsToAdd.length > 0) { return { ...f, exams: [...f.exams, ...folderExamsToAdd] }; } return f; })); } setUploadResults(results); setLoadingMessage(null); const hasErrors = results.some(r => r.status === 'error'); if (hasErrors) { if (!activeFolderId && folderId) setActiveFolderId(folderId); setCurrentView('FOLDER_DETAIL'); setIsUploadReportOpen(true); } else { if (!activeFolderId && folderId) setActiveFolderId(folderId); if (files.length === 1 && processedExams.length === 1) { setActiveExamId(processedExams[0].exam.id); setCurrentView('EXAM_TAKER'); } else { setCurrentView('FOLDER_DETAIL'); } } };
  const handleManualCreate = (fileName: string) => { if (!activeFolderId) return; const newExam: Exam = { id: crypto.randomUUID(), title: fileName, dateCreated: new Date().toISOString(), questions: [], isFinished: false }; setFolders(prev => prev.map(f => { if (f.id === activeFolderId) { return { ...f, exams: [...f.exams, newExam] }; } return f; })); setIsUploadReportOpen(false); setActiveExamId(newExam.id); setCurrentView('EXAM_TAKER'); };
  const updateExamInState = (updatedExam: Exam) => { setFolders(prev => prev.map(f => { if (f.id === activeFolderId) { return { ...f, exams: f.exams.map(e => e.id === updatedExam.id ? updatedExam : e) }; } return f; })); };

  const handleResetRequest = () => setIsResetModalOpen(true);

  const handleFinishRequest = () => setIsFinishModalOpen(true);
  const confirmFinishExam = () => {
      if (!activeFolderId || !activeExamId) return;
      setFolders(prev => prev.map(f => {
          if (f.id === activeFolderId) {
              return { ...f, exams: f.exams.map(e => e.id === activeExamId ? { ...e, isFinished: true } : e) };
          }
          return f;
      }));
      setIsFinishModalOpen(false);
  };

  const handleArchiveAndReset = () => { if (!activeFolderId || !activeExamId) return; setFolders(prev => prev.map(f => { if (f.id === activeFolderId) { const currentExam = f.exams.find(e => e.id === activeExamId); if (!currentExam) return f; const dateStr = new Date().toLocaleDateString('tr-TR', { hour: '2-digit', minute: '2-digit' }); const archivedExam: Exam = { ...JSON.parse(JSON.stringify(currentExam)), id: crypto.randomUUID(), title: `${currentExam.title} (Tamamlandı - ${dateStr})`, isFinished: true, }; const resetExam: Exam = { ...currentExam, isFinished: false, questions: currentExam.questions.map(q => ({ ...q, userSelection: null })) }; return { ...f, exams: [...f.exams.filter(e => e.id !== activeExamId), archivedExam, resetExam] }; } return f; })); setIsResetModalOpen(false); };
  const handleJustReset = () => { if (!activeFolderId || !activeExamId) return; setFolders(prev => prev.map(f => { if (f.id === activeFolderId) { return { ...f, exams: f.exams.map(e => e.id === activeExamId ? { ...e, isFinished: false, questions: e.questions.map(q => ({ ...q, userSelection: null })) } : e) }; } return f; })); setIsResetModalOpen(false); };
  const requestDeleteExam = (e: React.MouseEvent, examId: string) => { e.stopPropagation(); setExamToDeleteId(examId); };
  const confirmDeleteExam = () => { if (!examToDeleteId) return; setFolders(prev => prev.map(f => { if (f.id === activeFolderId) { return { ...f, exams: f.exams.filter(ex => ex.id !== examToDeleteId) }; } return f; })); setExamToDeleteId(null); };

  const scrollToBottom = () => {
      if (mainScrollRef.current) {
          mainScrollRef.current.scrollTo({ top: mainScrollRef.current.scrollHeight, behavior: 'smooth' });
      }
  };

  if (!currentUser) { return (<> <div className="absolute top-4 right-4 z-50"><button onClick={toggleDarkMode} className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors" title={darkMode ? "Aydınlık Mod" : "Karanlık Mod"}>{darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}</button></div><ServerConfigModal isOpen={isServerModalOpen} onClose={() => setIsServerModalOpen(false)} onSave={handleServerConfigSave} initialConfig={supabaseConfig} /><LoginScreen onLogin={handleLogin} onOpenServerSettings={() => setIsServerModalOpen(true)} isCloudConfigured={!!supabaseConfig.url}/></>); }
  if (currentView === 'LOADING') { return <LoadingScreen message={loadingMessage || undefined} />; }

  const examToDeleteTitle = examToDeleteId ? folders.find(f => f.id === activeFolderId)?.exams.find(e => e.id === examToDeleteId)?.title : "";

  return (
    <div className="min-h-[100dvh] bg-gray-50 dark:bg-gray-900 flex flex-col h-[100dvh] overflow-hidden relative">
      <ResetModal isOpen={isResetModalOpen} onClose={() => setIsResetModalOpen(false)} onSaveAndReset={handleArchiveAndReset} onJustReset={handleJustReset} />
      <FinishModal isOpen={isFinishModalOpen} onClose={() => setIsFinishModalOpen(false)} onConfirm={confirmFinishExam} />
      <DeleteModal isOpen={!!examToDeleteId} onClose={() => setExamToDeleteId(null)} onConfirm={confirmDeleteExam} itemName={examToDeleteTitle || "Sınav"} />
      <UploadReportModal results={uploadResults} isOpen={isUploadReportOpen} onClose={() => setIsUploadReportOpen(false)} onCreateManually={handleManualCreate} />

      {currentView !== 'EXAM_TAKER' && currentView !== 'STATISTICS' && currentView !== 'SETTINGS' && (
        <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 py-3 px-6 shadow-sm flex items-center justify-between flex-shrink-0 transition-colors">
          <div className="flex items-center gap-2"><div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-lg flex items-center justify-center text-white font-bold shadow-sm shadow-blue-500/30">A</div><span className="font-bold text-gray-800 dark:text-white text-lg tracking-tight">Sınav Asistanı</span></div>
          <div className="flex items-center gap-3">
             <div className={`hidden sm:flex items-center gap-1.5 px-2 py-1 rounded-md text-xs font-medium ${isCloudSession ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400'}`}>{isCloudSession ? <Wifi className="w-3 h-3" /> : <WifiOff className="w-3 h-3" />}{isCloudSession ? "Bulut" : "Yerel"}</div>
            <div className="flex items-center gap-2 mr-2"><div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-700 dark:text-blue-300 font-bold text-sm">{currentUser.substring(0, 2).toUpperCase()}</div><span className="text-sm font-medium text-gray-700 dark:text-gray-300 hidden sm:block">{currentUser}</span></div>
            <button onClick={toggleDarkMode} className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors" title={darkMode ? "Aydınlık Mod" : "Karanlık Mod"}>{darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}</button>
            <button onClick={handleLogout} className="p-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors" title="Çıkış Yap"><LogOut className="w-5 h-5" /></button>
          </div>
        </div>
      )}

      <div ref={mainScrollRef} className="flex-1 overflow-y-auto">
        {currentView === 'DASHBOARD' && renderDashboard()}
        {currentView === 'FOLDER_DETAIL' && renderFolderDetail()}
        {currentView === 'STATISTICS' && <StatisticsView folders={folders} onBack={() => setCurrentView('DASHBOARD')} />}
        {currentView === 'SETTINGS' && (<SettingsView folders={folders} defaultFolderId={defaultFolderId} setDefaultFolderId={setDefaultFolderId} darkMode={darkMode} toggleDarkMode={toggleDarkMode} onBack={() => setCurrentView('DASHBOARD')} />)}
        {currentView === 'EXAM_TAKER' && (() => {
          const activeExam = folders.find(f => f.id === activeFolderId)?.exams.find(e => e.id === activeExamId);
          if (!activeExam) return <div>Sınav bulunamadı</div>;
          return (
            <div className="h-full relative flex flex-col">
               <div className="absolute top-3 right-4 z-40 flex gap-2"><button onClick={toggleDarkMode} className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors shadow-sm border border-gray-200 dark:border-gray-600" title={darkMode ? "Aydınlık Mod" : "Karanlık Mod"}>{darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}</button></div>
              <ExamTaker 
                exam={activeExam} 
                onUpdateExam={updateExamInState} 
                onBack={() => { handleInternalNavigation(); setCurrentView('FOLDER_DETAIL'); }} 
                onResetRequest={handleResetRequest}
                onFinishRequest={handleFinishRequest}
                isSaving={isSaving}
                lastSaved={lastSaved}
                hasUnsavedChanges={isDirtyRef.current}
                scrollToBottom={scrollToBottom}
              />
            </div>
          );
        })()}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Folder, Exam, Question, AppView, Option } from './types';
