                return (<div key={opt.label} className="relative"><button onClick={() => handleOptionSelect(q.id, opt.label)} disabled={exam.isFinished || isEditMode} className={containerClass}><span className={labelClass} title={isEditMode ? "Doğru cevap olarak işaretle" : ""} onClick={(e) => { if(isEditMode) { e.stopPropagation(); toggleCorrectAnswer(q.id, opt.label); } }}>{opt.label})</span>{isEditMode ? (<input type="text" value={opt.text} onChange={(e) => handleOptionTextChange(q.id, opt.label, e.target.value)} className="flex-1 bg-transparent border-b border-transparent focus:border-blue-500 focus:outline-none w-full" placeholder="Şık metni..." onClick={e => e.stopPropagation()} />) : (<span className={textClass}>{opt.text}</span>)}{!isEditMode && isSelected && !exam.isFinished && (<CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-500" />)}{!isEditMode && exam.isFinished && isCorrect && (<CheckCircle className="absolute right-3 top-3 w-5 h-5 text-green-600 dark:text-green-400" />)}{!isEditMode && exam.isFinished && isSelected && !isCorrect && (<XCircle className="absolute right-3 top-3 w-5 h-5 text-red-500 dark:text-red-400" />)}</button>{isEditMode && (<button onClick={() => removeOption(q.id, opt.label)} className="absolute right-[-30px] top-4 text-red-300 hover:text-red-500"><MinusCircle className="w-5 h-5" /></button>)}</div>);
              })}
