  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>, targetFolderId?: string) => { const files = event.target.files; if (!files || files.length === 0) return; let folderId = targetFolderId || activeFolderId; if (!folderId && defaultFolderId) { const exists = folders.find(f => f.id === defaultFolderId); if (exists) { folderId = defaultFolderId; } else { setDefaultFolderId(null); } } let newFolderId = ""; if (!folderId) { newFolderId = crypto.randomUUID(); folderId = newFolderId; const newFolder: Folder = { id: newFolderId, name: "Genel", exams: [] }; setFolders(prev => [...prev, newFolder]); } setCurrentView('LOADING'); setUploadResults([]); const results: UploadResult[] = []; const processedExams: { folderId: string, exam: Exam }[] = []; for (let i = 0; i < files.length; i++) { const file = files[i]; setLoadingMessage(`Dosya işleniyor (${i + 1}/${files.length}): ${file.name}`); try { const mimeType = getMimeType(file); let data = ''; if (mimeType.startsWith('text/')) { data = await fileToText(file); } else { data = await fileToBase64(file); } const parsedData = await parseExamFile(data, mimeType); if (parsedData.questions.length === 0) { results.push({ fileName: file.name, status: 'error', message: "Soru bulunamadı veya dosya okunamadı." }); } else { const newExam: Exam = { id: crypto.randomUUID(), title: parsedData.title, dateCreated: new Date().toISOString(), questions: parsedData.questions, isFinished: false }; processedExams.push({ folderId: folderId!, exam: newExam }); results.push({ fileName: file.name, status: 'success' }); } } catch (error) { console.error(`Error processing file ${file.name}:`, error); results.push({ fileName: file.name, status: 'error', message: "İşlem hatası" }); } } if (processedExams.length > 0) { setFolders(prev => prev.map(f => { const folderExamsToAdd = processedExams.filter(pe => pe.folderId === f.id).map(pe => pe.exam); if (folderExamsToAdd.length > 0) { return { ...f, exams: [...f.exams, ...folderExamsToAdd] }; } return f; })); } setUploadResults(results); setLoadingMessage(null); const hasErrors = results.some(r => r.status === 'error'); if (hasErrors) { if (!activeFolderId && folderId) setActiveFolderId(folderId); setCurrentView('FOLDER_DETAIL'); setIsUploadReportOpen(true); } else { if (!activeFolderId && folderId) setActiveFolderId(folderId); if (files.length === 1 && processedExams.length === 1) { setActiveExamId(processedExams[0].exam.id); setCurrentView('EXAM_TAKER'); } else { setCurrentView('FOLDER_DETAIL'); } } };
