import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

const SYSTEM_INSTRUCTION = `
You are a highly precise exam digitizer. Your PRIMARY OBJECTIVE is to extract multiple-choice questions and apply the PROVIDED ANSWER KEY (Cevap Anahtarı) exactly as written.

CRITICAL INSTRUCTION FOR ANSWER KEYS:
1.  **SCAN FIRST:** Before extracting questions, look for a section titled "Cevap Anahtarı", "Yanıtlar", "Key", or a grid/table of numbers and letters at the END or BOTTOM of the document.
2.  **PRIORITIZE:** If an Answer Key is found, it is the SOURCE OF TRUTH. You must map the answer for Question 1 in the text to Answer 1 in the key, Question 2 to Answer 2, etc.
3.  **OVERRIDE:** Even if you think the answer key is wrong, USE THE ANSWER KEY. Do not try to solve the question if a key is present.
4.  **FORMAT:** The answer key might be linear (1-A, 2-C...) or tabular. Parse it carefully.

Standard Extraction Process:
1.  Identify questions numbered sequentially (1., 2., 3...).
2.  Extract the full question text.
3.  Extract options labeled A), B), C), D), E) (or A., B., etc).
4.  **Set 'correctAnswerLabel'**:
    *   **Scenario A (Key Found):** Set this field based strictly on the Answer Key (e.g., if Key says "1. C", set "C").
    *   **Scenario B (No Key):** Only if NO answer key is found in the entire document, try to solve the question to the best of your ability.
5.  Return the output STRICTLY as a JSON array.

Error Handling:
*   If a question is unreadable, skip it.
*   Do not hallucinate questions.
*   Ensure the JSON is valid.
`;

export const parseExamFile = async (data: string, mimeType: string): Promise<{ title: string, questions: Question[] }> => {
  let text = "";
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // We use gemini-2.5-flash for speed and good vision capabilities
    const modelId = "gemini-2.5-flash";

    // Determine if we should send as text or inlineData
    const isText = mimeType.startsWith('text/');

    const parts = [];
    if (isText) {
      parts.push({ text: data });
    } else {
      parts.push({ 
        inlineData: { 
          mimeType: mimeType, 
          data: data 
        } 
      });
    }

    parts.push({ 
      text: "Extract all multiple choice questions. FIND THE ANSWER KEY (Cevap Anahtarı) usually at the end and apply it to 'correctAnswerLabel' for each question. If the key says '1-A', Question 1 is A. Do not miss this." 
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        maxOutputTokens: 8192, // Explicitly set high limit for long exams
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "A generated title for the exam" },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.INTEGER, description: "The numeric index of the question as it appears in the text (e.g. 1, 2, 3)" },
                  text: { type: Type.STRING },
                  options: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        label: { type: Type.STRING, description: "e.g. A, B, C, D, E" },
                        text: { type: Type.STRING }
                      }
                    }
                  },
                  correctAnswerLabel: { type: Type.STRING, nullable: true, description: "CRITICAL: The correct option label (A, B, C...) taken STRICTLY from the Answer Key found in the document." }
                }
              }
            }
          }
        }
      }
    });

    text = response.text || "";
    if (!text) throw new Error("No response from AI");

    // Robust cleaning: remove markdown code blocks if present
    text = text.replace(/^```json\s*/gi, '').replace(/^```\s*/gi, '').replace(/```\s*$/gi, '').trim();

    let responseData;

    try {
        // Attempt 1: Standard Parse
        responseData = JSON.parse(text);
    } catch (e) {
        console.warn("JSON Parse failed, attempting to repair...", e);

        try {
            // Attempt 2: Truncation Repair (Fixing cut-off JSON at the end)
            const qStartIndex = text.indexOf('[');
            if (qStartIndex !== -1) {
                const lastObjectComma = text.lastIndexOf('},');
                if (lastObjectComma > qStartIndex) {
                    const repairedText = text.substring(0, lastObjectComma + 1) + ']}';
                    responseData = JSON.parse(repairedText);
                } else {
                     const lastBrace = text.lastIndexOf('}');
                     if (lastBrace > qStartIndex) {
                        const repairedText = text.substring(0, lastBrace + 1) + ']}';
                        responseData = JSON.parse(repairedText);
                     } else {
                        throw new Error("Cannot repair JSON structure");
                     }
                }
            } else {
                 throw new Error("No JSON array start found");
            }
        } catch (repairError) {
            console.error("Standard repair failed. Attempting strict object extraction to skip errors.", repairError);

            // Attempt 3: Regex Fallback (Skip invalid areas, extract valid objects individually)
            const extractedQuestions: any[] = [];

            // Regex to find potential question objects. 
            const matches = text.match(/\{[\s\S]*?"id"[\s\S]*?"text"[\s\S]*?"options"[\s\S]*?\}(?=\s*,|\s*\])/g);

            if (matches && matches.length > 0) {
                matches.forEach(match => {
                    try {
                        const q = JSON.parse(match);
                        if (q.id && q.text && Array.isArray(q.options)) {
                            extractedQuestions.push(q);
                        }
                    } catch (ignore) { 
                        // If a specific block is corrupted, we skip it
                    }
                });
            }

            // Fallback Title Extraction
            const titleMatch = text.match(/"title"\s*:\s*"([^"]+)"/);
            const fallbackTitle = titleMatch ? titleMatch[1] : "Kurtarılan Sınav (Kısmi Veri)";

            if (extractedQuestions.length > 0) {
                responseData = {
                    title: fallbackTitle,
                    questions: extractedQuestions
                };
            } else {
                console.error("All parsing attempts failed. Returning safe empty object.");
                return {
                    title: "İşlenemeyen Dosya",
                    questions: []
                };
            }
        }
    }

    // Final validation and transformation
    const questions: Question[] = (responseData.questions || []).map((q: any) => ({
      // If the AI returns the question number as ID (e.g., 1), keep it to preserve order/mapping logic if needed, 
      // but ensure it's a number. If it conflicts with existing logic, random is fine, 
      // but for "Answer Key" mapping visually, preserving the extracted ID is often better for debugging.
      // However, App.tsx generates new UUIDs for exams, but questions use number IDs.
      // We will prefer the extracted ID if valid, else random.
      id: (typeof q.id === 'number') ? q.id : Math.floor(Math.random() * 100000),
      text: q.text || "Soru metni okunamadı",
      options: Array.isArray(q.options) ? q.options : [],
      correctAnswerLabel: q.correctAnswerLabel ? q.correctAnswerLabel.trim().toUpperCase() : null, // Ensure uppercase
      userSelection: null
    }));

    return {
      title: responseData.title || "Yeni Sınav",
      questions
    };

  } catch (error) {
    console.error("Gemini parse error (Final Catch):", error);
    return {
        title: "Hata: Dosya Okunamadı",
        questions: []
    };
  }
};

