Input handling:
The input might be images or PDF text. Treat them carefully.
`;

export const parseExamFile = async (data: string, mimeType: string): Promise<{ title: string, questions: Question[] }> => {
  let text = "";
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Using gemini-2.5-flash for speed and vision capabilities.
    const modelId = "gemini-2.5-flash";

    const isText = mimeType.startsWith('text/');

    const parts = [];
    if (isText) {
      parts.push({ text: data });
    } else {
      parts.push({ 
        inlineData: { 
          mimeType: mimeType, 
          data: data 
        } 
      });
    }

    parts.push({ 
      text: "Step 1: Find the Answer Key (Cevap Anahtarı) at the end. Step 2: Extract it precisely. Step 3: Extract questions and apply the key to 'correctAnswerLabel'. Step 4: Output JSON." 
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        maxOutputTokens: 8192,
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Exam title (e.g. 'TYT Türkçe Deneme 1')" },
            detectedAnswerKeyRawContent: { 
                type: Type.STRING, 
                description: "CRITICAL: Copy the text/numbers of the answer key here found in the document. e.g. '1-A, 2-C...'" 
            },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.INTEGER, description: "Question number (1, 2, 3...)" },
                  text: { type: Type.STRING },
                  options: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        label: { type: Type.STRING, description: "A, B, C, D, E" },
                        text: { type: Type.STRING }
                      }
                    }
                  },
                  correctAnswerLabel: { type: Type.STRING, nullable: true, description: "The correct option (A, B, C...) derived STRICTLY from 'detectedAnswerKeyRawContent'." }
                }
              }
            }
          }
        }
      }
    });

    text = response.text || "";
    if (!text) throw new Error("No response from AI");

    // Robust cleaning
    text = text.replace(/^```json\s*/gi, '').replace(/^```\s*/gi, '').replace(/```\s*$/gi, '').trim();

    let responseData;

    try {
        responseData = JSON.parse(text);
    } catch (e) {
        console.warn("JSON Parse failed, attempting to repair...", e);
        // Basic repair for truncated JSON
        try {
            const qStartIndex = text.indexOf('[');
            if (qStartIndex !== -1) {
                const lastBrace = text.lastIndexOf('}');
                if (lastBrace > qStartIndex) {
                    const repairedText = text.substring(0, lastBrace + 1) + ']}';
                    responseData = JSON.parse(repairedText);
                } else { throw new Error("Repair failed"); }
            } else { throw new Error("No JSON structure"); }
        } catch (repairError) {
             // Fallback: Regex extraction
             const extractedQuestions: any[] = [];
             const matches = text.match(/\{[\s\S]*?"id"[\s\S]*?"text"[\s\S]*?"options"[\s\S]*?\}(?=\s*,|\s*\])/g);
             if (matches && matches.length > 0) {
                matches.forEach(match => {
                    try { extractedQuestions.push(JSON.parse(match)); } catch (ignore) {}
                });
             }
             if (extractedQuestions.length > 0) {
                 responseData = { title: "Kurtarılan Sınav", questions: extractedQuestions };
             } else {
                 return { title: "Hata: Okunamadı", questions: [] };
             }
        }
    }

    // Log the detected key for debugging purposes (optional)
    if (responseData.detectedAnswerKeyRawContent) {
        console.log("AI Detected Answer Key:", responseData.detectedAnswerKeyRawContent);
    }

    const questions: Question[] = (responseData.questions || []).map((q: any) => ({
      id: (typeof q.id === 'number') ? q.id : Math.floor(Math.random() * 100000),
      text: q.text || "Soru metni okunamadı",
      options: Array.isArray(q.options) ? q.options : [],
      correctAnswerLabel: q.correctAnswerLabel ? q.correctAnswerLabel.trim().toUpperCase() : null, 
      userSelection: null
    }));

    return {
      title: responseData.title || "Yeni Sınav",
      questions
    };

  } catch (error) {
    console.error("Gemini parse error:", error);
    return {
        title: "Hata: Dosya Okunamadı",
        questions: []
    };
  }
};

