] }; } return f; })); } setUploadResults(results); setLoadingMessage(null); const hasErrors = results.some(r => r.status === 'error'); if (hasErrors) { if (!activeFolderId && folderId) setActiveFolderId(folderId); setCurrentView('FOLDER_DETAIL'); setIsUploadReportOpen(true); } else { if (!activeFolderId && folderId) setActiveFolderId(folderId); if (files.length === 1 && processedExams.length === 1) { setActiveExamId(processedExams[0].exam.id); setCurrentView('EXAM_TAKER'); } else { setCurrentView('FOLDER_DETAIL'); } } };
